31	/* ==================== AI 模块全局上下文 ==================== */
32	static sm_context_t g_sm_ctx;           // 状态机
33	static audio_context_t g_audio_ctx;     // 音频
34	static llm_context_t g_llm_ctx;        // 大模型
35	static sound_detect_context_t g_sound_ctx;  // 声音检测
36	static care_context_t g_care_ctx;       // 主动关怀
37	
38	/* AI 模块是否初始化成功 */
39	static bool g_ai_initialized = false;
40	
41	/* ==================== AI 命令回调处理 ==================== */
42	
43	/**
44	 * 处理来自手机端或云端的 AI 命令
45	 * 成员二的 AI 模块可以通过此接口接收控制命令
46	 */
47	static void on_ai_command_received(const char *action, const char *param)
48	{
49	    printf("AI command: action=%s, param=%s\n", action, param);
50	
51	    if (strcmp(action, "start_voice") == 0) {
52	        /* 开始语音监听 */
53	        robot_ui_set_status(ROBOT_STATUS_LISTENING);
54	        robot_ui_set_face(ROBOT_FACE_THINKING);
55	        robot_ui_set_ai_reply("Listening...\nPlease speak.");
56	
57	        /* 调用成员二的 AI 模块开始录音 */
58	        if (g_ai_initialized) {
59	            audio_record_start(&g_audio_ctx, NULL, 0);
60	            sm_handle_event(&g_sm_ctx, SM_EVENT_WAKEUP);
61	        }
62	    }
63	    else if (strcmp(action, "stop_voice") == 0) {
64	        /* 停止语音监听 */
65	        robot_ui_set_status(ROBOT_STATUS_IDLE);
66	        robot_ui_set_face(ROBOT_FACE_HAPPY);
67	
68	        /* 调用成员二的 AI 模块停止录音 */
69	        if (g_ai_initialized) {
70	            audio_record_stop(&g_audio_ctx);
71	            sm_handle_event(&g_sm_ctx, SM_EVENT_VOICE_COMPLETE);
72	        }
73	    }
74	    else if (strcmp(action, "ai_reply") == 0) {
75	        /* 显示 AI 回复 */
76	        robot_ui_set_status(ROBOT_STATUS_SPEAKING);
77	        robot_ui_set_face(ROBOT_FACE_HAPPY);
78	        robot_ui_set_ai_reply(param);
79	
80	        /* 播放语音回复 */
81	        if (g_ai_initialized) {
82	            audio_play_start(&g_audio_ctx, NULL, 0);
83	        }
84	    }
85	    else if (strcmp(action, "start_remind") == 0) {
86	        /* 开始提醒 */
87	        robot_ui_set_status(ROBOT_STATUS_REMINDING);
88	        robot_ui_set_face(ROBOT_FACE_WORRIED);
89	        robot_ui_show_reminder("Reminder", param);
90	    }
91	    else if (strcmp(action, "start_alarm") == 0) {
92	        /* 开始报警 */
93	        robot_ui_show_alarm(param);
94	
95	        /* 触发报警 */
96	        if (g_ai_initialized) {
97	            sm_handle_event(&g_sm_ctx, SM_EVENT_ALARM_DETECTED);
98	            report_alarm("sound_abnormal", param);
99	        }
100	    }
101	    else if (strcmp(action, "stop_alarm") == 0) {
102	        /* 停止报警 */
103	        robot_ui_close_alarm();
104	
105	        if (g_ai_initialized) {
106	            sm_handle_event(&g_sm_ctx, SM_EVENT_ALARM_CLEARED);
107	        }
108	    }
109	    else if (strcmp(action, "set_face") == 0) {
110	        /* 设置表情 */
111	        if (strcmp(param, "happy") == 0) {
112	            robot_ui_set_face(ROBOT_FACE_HAPPY);
113	        } else if (strcmp(param, "thinking") == 0) {
114	            robot_ui_set_face(ROBOT_FACE_THINKING);
115	        } else if (strcmp(param, "sleepy") == 0) {
116	            robot_ui_set_face(ROBOT_FACE_SLEEPY);
117	        } else if (strcmp(param, "surprised") == 0) {
118	            robot_ui_set_face(ROBOT_FACE_SURPRISED);
119	        } else if (strcmp(param, "worried") == 0) {
120	            robot_ui_set_face(ROBOT_FACE_WORRIED);
121	        }
122	    }
123	    else if (strcmp(action, "send_text") == 0) {
124	        /* 发送文本到 AI */
125	        if (g_ai_initialized) {
126	            robot_ui_set_status(ROBOT_STATUS_LISTENING);
127	            robot_ui_set_face(ROBOT_FACE_THINKING);
128	            llm_send_request(&g_llm_ctx, param, NULL);
129	        }
130	    }
131	}
