133	/* ==================== AI 模块回调函数 ==================== */
134	
135	/**
136	 * VAD 回调 - 语音活动检测
137	 */
138	static void vad_callback(bool speech_detected, void *user_data)
139	{
140	    if (speech_detected) {
141	        printf("[VAD] Speech detected\n");
142	        sm_handle_event(&g_sm_ctx, SM_EVENT_WAKEUP);
143	    } else {
144	        printf("[VAD] Speech ended\n");
145	        sm_handle_event(&g_sm_ctx, SM_EVENT_VOICE_COMPLETE);
146	    }
147	}
148	
149	/**
150	 * LLM 回调 - AI 回复
151	 */
152	static void llm_response_callback(const char *response, void *user_data)
153	{
154	    printf("[LLM] Response: %s\n", response);
155	
156	    /* 更新 UI 显示 AI 回复 */
157	    robot_ui_set_status(ROBOT_STATUS_SPEAKING);
158	    robot_ui_set_face(ROBOT_FACE_HAPPY);
159	    robot_ui_set_ai_reply(response);
160	
161	    /* 播放语音 */
162	    if (g_ai_initialized) {
163	        audio_play_start(&g_audio_ctx, NULL, 0);
164	    }
165	
166	    /* 通知状态机 */
167	    sm_handle_event(&g_sm_ctx, SM_EVENT_AI_RESPONSE);
168	}
169	
170	/**
171	 * 声音检测回调 - 异常声音
172	 */
173	static void sound_alarm_callback(const char *sound_type, int confidence, void *user_data)
174	{
175	    printf("[SoundDetect] Alarm: %s (confidence: %d)\n", sound_type, confidence);
176	
177	    /* 触发报警 */
178	    robot_ui_show_alarm(sound_type);
179	    report_alarm(sound_type, "Abnormal sound detected");
180	
181	    /* 通知状态机 */
182	    sm_handle_event(&g_sm_ctx, SM_EVENT_ALARM_DETECTED);
183	}
184	
185	/**
186	 * 主动关怀回调
187	 */
188	static void care_remind_callback(const char *title, const char *content, void *user_data)
189	{
190	    printf("[Care] Reminder: %s - %s\n", title, content);
191	
192	    /* 显示提醒 */
193	    robot_ui_set_status(ROBOT_STATUS_REMINDING);
194	    robot_ui_set_face(ROBOT_FACE_WORRIED);
195	    robot_ui_show_reminder(title, content);
196	
197	    /* 发送推送 */
198	    push_send_health_reminder(title, content);
199	}
200	
201	/* ==================== MQTT 消息回调处理 ==================== */
202	
203	/**
204	 * 处理来自 MQTT 的消息
205	 * 解析命令并转发给 AI 命令处理函数
206	 */
207	static void on_mqtt_message_received(const char *topic, const char *payload)
208	{
209	    printf("MQTT received: topic=%s\n", topic);
210	
211	    /* 解析 JSON 命令 */
212	    cJSON *root = cJSON_Parse(payload);
213	    if (!root) {
214	        printf("JSON parse failed\n");
215	        return;
216	    }
217	
218	    cJSON *action = cJSON_GetObjectItem(root, "action");
219	    cJSON *param = cJSON_GetObjectItem(root, "param");
220	
221	    if (action && action->valuestring) {
222	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
223	        on_ai_command_received(action->valuestring, param_str);
224	    }
225	
226	    cJSON_Delete(root);
227	}
