266	/* ==================== 按钮事件处理 ==================== */
267	static void btn_event_handler(lv_event_t *e)
268	{
269	    lv_event_code_t code = lv_event_get_code(e);
270	    ui_view_t view = (ui_view_t)lv_event_get_user_data(e);
271	
272	    if (code == LV_EVENT_CLICKED) {
273	        switch (view) {
274	            case UI_VIEW_REMIND:
275	                robot_ui_show_reminder("Health", "Time to take medicine!");
276	                break;
277	            case UI_VIEW_SETTING:
278	                // TODO: 打开设置界面
279	                break;
280	            case UI_VIEW_ALARM:
281	                robot_ui_show_alarm("Abnormal detected!\nPlease confirm if help is needed.");
282	                break;
283	            default:
284	                break;
285	        }
286	    }
287	}
