357	/* ==================== 设置表情 ==================== */
358	void robot_ui_set_face(robot_face_t face)
359	{
360	    if (face >= ROBOT_FACE_MAX) return;
361	
362	    current_face = face;
363	
364	    if (lbl_face) {
365	        lv_label_set_text(lbl_face, face_array[face]);
366	
367	        /* 根据表情改变颜色 */
368	        switch (face) {
369	            case ROBOT_FACE_HAPPY:
370	                lv_obj_set_style_text_color(lbl_face, lv_color_hex(0xFFEB3B), 0); // 黄色
371	                break;
372	            case ROBOT_FACE_THINKING:
373	                lv_obj_set_style_text_color(lbl_face, lv_color_hex(0x2196F3), 0); // 蓝色
374	                break;
375	            case ROBOT_FACE_SLEEPY:
376	                lv_obj_set_style_text_color(lbl_face, lv_color_hex(0x9E9E9E), 0); // 灰色
377	                break;
378	            case ROBOT_FACE_ALARM:
379	                lv_obj_set_style_text_color(lbl_face, lv_color_hex(0xF44336), 0); // 红色
380	                break;
381	            default:
382	                lv_obj_set_style_text_color(lbl_face, lv_color_hex(0xFFEB3B), 0);
383	                break;
384	        }
385	    }
386	}
