201	/* ==================== MQTT 消息回调处理 ==================== */
202	
203	/**
204	 * 处理来自 MQTT 的消息
205	 * 解析命令并转发给 AI 命令处理函数
206	 */
207	static void on_mqtt_message_received(const char *topic, const char *payload)
208	{
209	    printf("MQTT received: topic=%s\n", topic);
210	
211	    /* 解析 JSON 命令 */
212	    cJSON *root = cJSON_Parse(payload);
213	    if (!root) {
214	        printf("JSON parse failed\n");
215	        return;
216	    }
217	
218	    cJSON *action = cJSON_GetObjectItem(root, "action");
219	    cJSON *param = cJSON_GetObjectItem(root, "param");
220	
221	    if (action && action->valuestring) {
222	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
223	        on_ai_command_received(action->valuestring, param_str);
224	    }
225	
226	    cJSON_Delete(root);
227	}
