230	int main(int argc, char *argv[])
231	{
232	    printf("ZhiAi Companion starting...\n");
233	
234	    /* ===== 初始化网络通信 ===== */
235	    network_comm_init();
236	
237	    /* ===== 连接 WiFi ===== */
238	    wifi_connect("魔王城", "sjmbahczdszjj");
239	
240	    /* ===== 初始化手机推送服务 ===== */
241	    /* PushPlus (Android 微信推送) */
242	    push_init(PUSH_SERVICE_PUSHPLUS, "1043ad84f9ba4dbb921756173d36277a");
243	    /* Bark (iPad iOS 推送) */
244	    push_init(PUSH_SERVICE_BARK, "726d1da9c292efcf947a85897c38310f6200a45c60ec8683813ae4d06fe67be9");
245	
246	    /* ===== 注册回调函数 ===== */
247	    network_set_mqtt_callback(on_mqtt_message_received);
248	    network_set_ai_command_callback(on_ai_command_received);
249	
250	    /* ===== 初始化 AI 模块 (成员二) ===== */
251	    printf("Initializing AI modules...\n");
252	
253	    /* 初始化状态机 */
254	    if (sm_init(&g_sm_ctx) == 0) {
255	        printf("State machine initialized\n");
256	    }
257	
258	    /* 初始化音频模块 */
259	    audio_config_t audio_config = {
260	        .sample_rate = AUDIO_RATE_16K,
261	        .channels = AUDIO_CH_MONO,
262	        .bits_per_sample = 16
263	    };
264	    if (audio_init(&g_audio_ctx, &audio_config) == 0) {
265	        printf("Audio module initialized\n");
266	        /* 启用 VAD 检测 */
267	        audio_vad_enable(&g_audio_ctx, vad_callback, NULL);
268	    }
269	
270	    /* 初始化 LLM 模块 */
271	    if (llm_init(&g_llm_ctx, NULL) == 0) {
272	        printf("LLM module initialized\n");
273	    }
274	
275	    /* 初始化声音检测 */
276	    if (sound_detect_init(&g_sound_ctx) == 0) {
277	        printf("Sound detect initialized\n");
278	        /* 注册报警回调 */
279	        sound_detect_set_alarm_callback(&g_sound_ctx, sound_alarm_callback, NULL);
280	    }
281	
282	    /* 初始化主动关怀 */
283	    if (care_init(&g_care_ctx) == 0) {
284	        printf("Care module initialized\n");
285	        /* 注册提醒回调 */
286	        care_set_remind_callback(&g_care_ctx, care_remind_callback, NULL);
287	    }
288	
289	    g_ai_initialized = true;
290	    printf("AI modules initialization done\n");
291	
292	    /* ===== 初始化触摸交互 UI（先初始化） ===== */
293	    touch_ui_init();
294	
295	    /* ===== 初始化机器人 UI ===== */
296	    robot_ui_init();
297	
298	    /* ===== 添加默认提醒 ===== */
299	    touch_ui_add_reminder("Medicine", "08:00");
300	    touch_ui_add_reminder("Drink Water", "10:00");
301	    touch_ui_add_reminder("Take a Walk", "16:00");
302	
303	    /* ===== 设置初始状态 ===== */
304	    robot_ui_set_status(ROBOT_STATUS_IDLE);
305	    robot_ui_set_face(ROBOT_FACE_HAPPY);
306	    robot_ui_set_ai_reply("Hello! I am ZhiAi.\nHow can I help you?");
307	
308	    /* ===== 显示主菜单 ===== */
309	    touch_ui_show_menu(MENU_TYPE_MAIN);
310	
311	    printf("ZhiAi Companion started!\n");
312	
313	    /* 主循环 */
314	    while (1) {
315	        lvgl_timer_handler();
316	
317	        /* 运行 AI 模块 */
318	        if (g_ai_initialized) {
319	            sm_run(&g_sm_ctx);
320	        }
321	
322	        usleep(5000); // 5ms 刷新周期
323	    }
324	
325	    return 0;
326	}
