182	static void create_face_area(lv_obj_t *parent)
183	{
184	    /* 表情容器 */
185	    lv_obj_t *container = lv_obj_create(parent);
186	    lv_obj_set_size(container, LV_PCT(100), LV_SIZE_CONTENT);
187	    lv_obj_align(container, LV_ALIGN_TOP_MID, 0, 70);
