189	    lv_obj_set_style_border_width(container, 0, 0);
190	    lv_obj_set_style_radius(container, 0, 0);
191	    lv_obj_set_flex_flow(container, LV_FLEX_FLOW_COLUMN);
192	    lv_obj_set_flex_align(container, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
193	
194	    /* 表情标签 */
195	    lbl_face = lv_label_create(container);
196	    lv_label_set_text(lbl_face, face_array[ROBOT_FACE_HAPPY]);
197	    lv_obj_add_style(lbl_face, &style_face, 0);
198	    lv_obj_set_style_text_font(lbl_face, &lv_font_montserrat_48, 0);
199	
200	    /* 状态文字 */
