203	    lv_obj_set_style_text_color(lbl_reminder, lv_color_hex(0xCCCCCC), 0);
204	    lv_obj_set_style_text_font(lbl_reminder, &lv_font_montserrat_22, 0);
205	    lv_obj_set_style_pad_top(lbl_reminder, 10, 0);
206	
207	    /* 启动表情动画 - 上下浮动 */
208	    lv_anim_init(&anim_face);
209	    lv_anim_set_var(&anim_face, lbl_face);
210	    lv_anim_set_values(&anim_face, -10, 10);
211	    lv_anim_set_time(&anim_face, 1000);
212	    lv_anim_set_playback_time(&anim_face, 1000);
213	    lv_anim_set_repeat_count(&anim_face, LV_ANIM_REPEAT_INFINITE);
214	    lv_anim_set_exec_cb(&anim_face, (lv_anim_exec_xcb_t)lv_obj_set_y);
215	    lv_anim_start(&anim_face);
216	}
