+    char time_str[16];
+
+    /* 获取当前时间 */
+    time(&now);
+
+    /* 设置北京时间 (UTC+8) */
+    now += 8 * 3600;
+
+    tm_info = gmtime(&now);
+
+    /* 格式化为 HH:MM */
+    snprintf(time_str, sizeof(time_str), "%02d:%02d",
+             tm_info->tm_hour, tm_info->tm_min);
