101	/* ==================== 更新时间显示（北京时间） ==================== */
102	static void update_time_display(void)
103	{
104	    time_t now;
105	    struct tm *tm_info;
106	    char time_str[16];
107	
108	    /* 获取当前时间 */
109	    time(&now);
110	
111	    /* 设置北京时间 (UTC+8) */
112	    now += 8 * 3600;
113	
114	    tm_info = gmtime(&now);
115	
116	    /* 格式化为 HH:MM */
117	    snprintf(time_str, sizeof(time_str), "%02d:%02d",
118	             tm_info->tm_hour, tm_info->tm_min);
119	
120	    /* 更新时间标签 */
121	    if (lbl_time) {
122	        lv_label_set_text(lbl_time, time_str);
123	    }
124	}
