478	void robot_ui_show_reminder(const char *title, const char *content)
479	{
480	    /* 创建提醒弹窗 */
481	    lv_obj_t *mbox = lv_msgbox_create(NULL);
482	    if (mbox == NULL) return;
483	
484	    lv_msgbox_add_title(mbox, title);
485	    lv_msgbox_add_text(mbox, content);
486	    lv_msgbox_add_close_button(mbox);
487	    lv_obj_center(mbox);
488	    lv_obj_set_style_bg_color(mbox, lv_color_hex(0x2D2D44), 0);
