492	/* ==================== 显示报警 ==================== */
493	void robot_ui_show_alarm(const char *content)
494	{
495	    /* 切换到报警屏幕 */
496	    lv_scr_load(scr_alarm);
497	
498	    /* 设置报警表情 */
499	    robot_ui_set_face(ROBOT_FACE_ALARM);
500	    robot_ui_set_status(ROBOT_STATUS_ALARM);
501	
502	    /* 启动报警闪烁动画 */
503	    lv_anim_start(&anim_blink);
504	}
