506	/* ==================== 关闭报警 ==================== */
507	void robot_ui_close_alarm(void)
508	{
509	    /* 停止闪烁动画 */
510	    lv_anim_del(&anim_blink, (lv_anim_exec_xcb_t)lv_obj_set_style_bg_opa);
511	
512	    /* 返回主界面 */
513	    lv_scr_load(scr_main);
514	
515	    /* 恢复正常状态 */
516	    robot_ui_set_face(ROBOT_FACE_HAPPY);
517	    robot_ui_set_status(ROBOT_STATUS_IDLE);
518	}
