525	
526	/* 菜单项点击事件 */
527	static void menu_item_event_handler(lv_event_t *e)
528	{
529	    int index = (int)(intptr_t)lv_event_get_user_data(e);
530	
531	    /* 触摸反馈 */
532	    touch_ui_play_sound("click");
533	
534	    switch (index) {
535	        case 0: // 语音聊天
536	            touch_ui_set_mode(MODE_LISTENING);
537	            break;
538	        case 1: // 查看提醒
539	            touch_ui_show_menu(MENU_TYPE_REMIND);
540	            break;
