300	static void btn_event_handler(lv_event_t *e)
301	{
302	    lv_event_code_t code = lv_event_get_code(e);
303	    ui_view_t view = (ui_view_t)lv_event_get_user_data(e);
304	
305	    if (code == LV_EVENT_CLICKED) {
306	        switch (view) {
307	            case UI_VIEW_REMIND:
308	                robot_ui_show_reminder("健康", "该吃药了！");
309	                break;
310	            case UI_VIEW_SETTING:
311	                // TODO: 打开设置界面
312	                break;
313	            case UI_VIEW_ALARM:
314	                robot_ui_show_alarm("检测到异常！\n请确认是否需要帮助。");
315	                break;
316	            default:
317	                break;
318	        }
319	    }
320	}
