296	/* ==================== 按钮事件处理 ==================== */
297	static void btn_event_handler(lv_event_t *e)
298	{
299	    lv_event_code_t code = lv_event_get_code(e);
300	    ui_view_t view = (ui_view_t)lv_event_get_user_data(e);
301	
302	    if (code == LV_EVENT_CLICKED) {
303	        switch (view) {
304	            case UI_VIEW_REMIND:
305	                robot_ui_show_reminder("Health", "Time to take medicine!");
306	                break;
307	            case UI_VIEW_SETTING:
308	                touch_ui_show_menu(MENU_TYPE_SETTING);
309	                break;
310	            case UI_VIEW_ALARM:
311	                robot_ui_show_alarm("Abnormal detected!\nPlease confirm if help is needed.");
312	                break;
313	            case UI_VIEW_MAIN:
314	                /* 报警界面 Back 按钮：关闭报警，返回主界面 */
315	                robot_ui_close_alarm();
316	                break;
317	            default:
318	                break;
319	        }
320	    }
321	}
