501	/* ==================== 关闭报警 ==================== */
502	void robot_ui_close_alarm(void)
503	{
504	    /* 停止闪烁动画 */
505	    /* v9 语义: lv_anim_delete(var, exec_cb) 第一个参数是动画绑定的对象
506	     * (anim_blink.var == scr_alarm), 不是 lv_anim_t 结构体地址 */
507	    lv_anim_delete(anim_blink.var, anim_blink_update);
508	
509	    /* 返回主界面 */
510	    lv_scr_load(scr_main);
511	
512	    /* 恢复正常状态 */
513	    robot_ui_set_face(ROBOT_FACE_HAPPY);
514	    robot_ui_set_status(ROBOT_STATUS_IDLE);
515	}
