128	/* ==================== 初始化触摸交互 UI ==================== */
129	void touch_ui_init(void)
130	{
131	    /* 初始化样式 */
132	    init_elder_styles();
133	
134	    /* 初始化提醒列表 */
135	    memset(reminders, 0, sizeof(reminders));
136	    reminder_count = 0;
137	
138	    /* 面板句柄复位: NuttX builtin 应用重新运行时 .bss 不清零,
139	     * 若残留上一次运行的面板指针, 之后 lv_obj_del() 会去删除已
140	     * 失效的 LVGL 对象而导致 hardfault */
141	    menu_panel = NULL;
142	    setting_panel = NULL;
143	    reminder_panel = NULL;
144	
145	    /* 获取当前活动屏幕 */
146	    current_screen = lv_scr_act();
147	    lv_obj_add_style(current_screen, &style_elder, 0);
148	
149	    printf("touch_ui init done\n");
150	}
