152	/* ==================== 显示菜单 ==================== */
153	void touch_ui_show_menu(menu_type_t type)
154	{
155	    /* 清除所有旧面板. 注意 setting_panel 是活动屏的兄弟节点,
156	     * 不挂在 menu_panel 下, 只删 menu_panel 会遗留旧设置面板,
157	     * 导致新旧面板重叠且整棵对象树泄漏 */
158	    if (menu_panel) {
159	        lv_obj_del(menu_panel);
160	        menu_panel = NULL;
161	    }
162	    if (setting_panel) {
163	        lv_obj_del(setting_panel);
164	        setting_panel = NULL;
165	    }
166	    if (reminder_panel) {
167	        lv_obj_del(reminder_panel);
168	        reminder_panel = NULL;
169	    }
170	
171	    /* 创建菜单面板 */
172	    create_menu_panel(type);
173	}
174	
175	/* ==================== 隐藏菜单 ==================== */
176	void touch_ui_hide_menu(void)
177	{
178	    if (menu_panel) {
179	        lv_obj_del(menu_panel);
180	        menu_panel = NULL;
181	    }
182	}
183	
184	/* ==================== 返回上一级 ==================== */
185	void touch_ui_go_back(void)
186	{
187	    /* 隐藏所有面板 */
188	    touch_ui_hide_menu();
189	
190	    if (setting_panel) {
191	        lv_obj_del(setting_panel);
192	        setting_panel = NULL;
193	    }
194	
195	    if (reminder_panel) {
196	        lv_obj_del(reminder_panel);
197	        reminder_panel = NULL;
198	    }
199	
200	    /* 播放返回音效 */
201	    touch_ui_play_sound("back");
202	}
