204	/* ==================== 创建菜单面板 ==================== */
205	static void create_menu_panel(menu_type_t type)
206	{
207	    /* 菜单容器 */
208	    menu_panel = lv_obj_create(current_screen);
209	    lv_obj_set_size(menu_panel, LV_PCT(95), LV_PCT(85));
210	    lv_obj_align(menu_panel, LV_ALIGN_CENTER, 0, 0);
