212	    lv_obj_set_flex_flow(menu_panel, LV_FLEX_FLOW_COLUMN);
213	    lv_obj_set_flex_align(menu_panel, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
214	    lv_obj_set_style_pad_all(menu_panel, 20, 0);
215	    lv_obj_set_style_pad_row(menu_panel, 15, 0);
216	
217	    /* 标题 */
218	    lv_obj_t *title = lv_label_create(menu_panel);
219	    switch (type) {
220	        case MENU_TYPE_MAIN:
221	            lv_label_set_text(title, "[M] Main Menu");
222	            break;
223	        case MENU_TYPE_REMIND:
224	            lv_label_set_text(title, "[T] Reminders");
225	            break;
226	        case MENU_TYPE_SETTING:
227	            lv_label_set_text(title, "[S] Settings");
228	            break;
229	        case MENU_TYPE_ABOUT:
230	            lv_label_set_text(title, "[?] About");
231	            break;
232	        default:
233	            lv_label_set_text(title, "Menu");
234	            break;
235	    }
236	    lv_obj_set_style_text_font(title, &lv_font_montserrat_28, 0);
237	    lv_obj_set_style_text_color(title, lv_color_hex(0xFFEB3B), 0);
238	    lv_obj_set_style_pad_bottom(title, 20, 0);
