244	            create_menu_item(menu_panel, "[T] View Reminders", "Check today's reminders", 1);
245	            create_menu_item(menu_panel, "[S] Settings", "Volume, brightness etc.", 2);
246	            create_menu_item(menu_panel, "[C] Emergency Call", "Contact family", 3);
247	            create_menu_item(menu_panel, "[?] About", "Version info", 4);
