252	            break;
253	
254	        case MENU_TYPE_SETTING:
255	            create_setting_panel();
256	            break;
257	
258	        case MENU_TYPE_ABOUT:
259	            create_about_info(menu_panel);
260	            break;
261	
262	        default:
263	            break;
264	    }
265	
266	    /* 返回按钮 */
