550	    touch_ui_play_sound("click");
551	
552	    switch (index) {
553	        case 0: // 语音聊天
554	            touch_ui_set_mode(MODE_LISTENING);
555	            break;
556	        case 1: // 查看提醒
557	            touch_ui_show_menu(MENU_TYPE_REMIND);
558	            break;
559	        case 2: // 系统设置
560	            touch_ui_show_menu(MENU_TYPE_SETTING);
561	            break;
562	        case 3: // 紧急联系
563	            touch_ui_show_setting_detail("Emergency", "Calling family...\nPlease wait");
564	            break;
565	        case 4: // 关于
566	            touch_ui_show_menu(MENU_TYPE_ABOUT);
567	            break;
568	        default:
569	            break;
570	    }
