27	/**
28	 * 处理来自手机端或云端的 AI 命令
29	 * 成员二的 AI 模块可以通过此接口接收控制命令
30	 */
31	static void on_ai_command_received(const char *action, const char *param)
32	{
33	    printf("AI command: action=%s, param=%s\n", action, param);
34	
35	    if (strcmp(action, "start_voice") == 0) {
36	        /* 开始语音监听 */
37	        robot_ui_set_status(ROBOT_STATUS_LISTENING);
38	        robot_ui_set_face(ROBOT_FACE_THINKING);
39	        robot_ui_set_ai_reply("Listening...\nPlease speak.");
40	        // TODO: 调用成员二的 AI 模块开始录音
41	    }
42	    else if (strcmp(action, "stop_voice") == 0) {
43	        /* 停止语音监听 */
44	        robot_ui_set_status(ROBOT_STATUS_IDLE);
45	        robot_ui_set_face(ROBOT_FACE_HAPPY);
46	        // TODO: 调用成员二的 AI 模块停止录音
47	    }
48	    else if (strcmp(action, "ai_reply") == 0) {
49	        /* 显示 AI 回复 */
50	        robot_ui_set_status(ROBOT_STATUS_SPEAKING);
51	        robot_ui_set_face(ROBOT_FACE_HAPPY);
52	        robot_ui_set_ai_reply(param);
53	        // TODO: 播放语音回复
54	    }
55	    else if (strcmp(action, "start_remind") == 0) {
56	        /* 开始提醒 */
57	        robot_ui_set_status(ROBOT_STATUS_REMINDING);
58	        robot_ui_set_face(ROBOT_FACE_WORRIED);
59	        robot_ui_show_reminder("Reminder", param);
60	    }
61	    else if (strcmp(action, "start_alarm") == 0) {
62	        /* 开始报警 */
63	        robot_ui_show_alarm(param);
64	        // TODO: 调用成员二的 AI 模块触发报警
65	    }
66	    else if (strcmp(action, "stop_alarm") == 0) {
67	        /* 停止报警 */
68	        robot_ui_close_alarm();
69	    }
70	    else if (strcmp(action, "set_face") == 0) {
71	        /* 设置表情 */
72	        if (strcmp(param, "happy") == 0) {
73	            robot_ui_set_face(ROBOT_FACE_HAPPY);
74	        } else if (strcmp(param, "thinking") == 0) {
75	            robot_ui_set_face(ROBOT_FACE_THINKING);
76	        } else if (strcmp(param, "sleepy") == 0) {
77	            robot_ui_set_face(ROBOT_FACE_SLEEPY);
78	        } else if (strcmp(param, "surprised") == 0) {
79	            robot_ui_set_face(ROBOT_FACE_SURPRISED);
80	        } else if (strcmp(param, "worried") == 0) {
81	            robot_ui_set_face(ROBOT_FACE_WORRIED);
82	        }
83	    }
84	}
