87	
88	/**
89	 * 处理来自 MQTT 的消息
90	 * 解析命令并转发给 AI 命令处理函数
91	 */
92	static void on_mqtt_message_received(const char *topic, const char *payload)
93	{
94	    printf("MQTT received: topic=%s\n", topic);
95	
96	    /* 解析 JSON 命令 */
97	    cJSON *root = cJSON_Parse(payload);
98	    if (!root) {
99	        printf("JSON parse failed\n");
100	        return;
101	    }
102	
103	    cJSON *action = cJSON_GetObjectItem(root, "action");
104	    cJSON *param = cJSON_GetObjectItem(root, "param");
105	
106	    if (action && action->valuestring) {
107	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
108	        on_ai_command_received(action->valuestring, param_str);
109	    }
110	
111	    cJSON_Delete(root);
112	}
