114	/* 主函数 */
115	int main(int argc, char *argv[])
116	{
117	    printf("ZhiAi Companion starting...\n");
118	
119	    /* ===== 初始化 LVGL 与显示设备（必须在 UI 创建之前） ===== */
120	    lv_init();
121	    lv_nuttx_dsc_t lv_info = {0};
122	    lv_nuttx_result_t lv_result = {0};
123	    lv_nuttx_dsc_init(&lv_info);
124	    lv_nuttx_init(&lv_info, &lv_result);
125	    if (lv_result.disp == NULL)
126	    {
127	        printf("LVGL display init failed!\n");
128	        return 1;
129	    }
130	
131	    /* ===== 初始化网络通信 ===== */
132	    network_comm_init();
133	
134	    /* ===== 连接 WiFi ===== */
135	    wifi_connect("魔王城", "sjmbahczdszjj");
136	
137	    /* ===== 启动网络后台任务 =====
138	     * 负责 MQTT 连接 broker.emqx.io:1883、收消息、发心跳。
139	     * network_task() 一直存在但从来没被创建过，所以 MQTT 一次都没连上过。
140	     * 它自己会轮询 wifi_config.connected，所以放在 wifi_connect() 之后创建。
141	     */
142	    if (task_create("net_task", 100, 12288, (main_t)network_task, NULL) < 0) {
143	        printf("net_task create failed\n");
144	    }
145	
146	    /* ===== 初始化手机推送服务 ===== */
147	    /* PushPlus (Android 微信推送) */
148	    push_init(PUSH_SERVICE_PUSHPLUS, "1043ad84f9ba4dbb921756173d36277a");
149	    /* Bark (iPad iOS 推送) */
150	    push_init(PUSH_SERVICE_BARK, "726d1da9c292efcf947a85897c38310f6200a45c60ec8683813ae4d06fe67be9");
151	
152	    /* ===== 注册回调函数 ===== */
153	    network_set_mqtt_callback(on_mqtt_message_received);
154	    network_set_ai_command_callback(on_ai_command_received);
155	
156	    /* ===== 初始化机器人 UI（先创建主屏并 lv_scr_load，成为活动屏） ===== */
157	    robot_ui_init();
158	
159	    /* ===== 初始化触摸交互 UI（须在活动屏 = 主屏之后, 菜单才可见） ===== */
160	    touch_ui_init();
161	
162	    /* ===== 添加默认提醒 ===== */
163	    touch_ui_add_reminder("Medicine", "08:00");
164	    touch_ui_add_reminder("Drink Water", "10:00");
165	    touch_ui_add_reminder("Take a Walk", "16:00");
166	
167	    /* ===== 设置初始状态 ===== */
168	    robot_ui_set_status(ROBOT_STATUS_IDLE);
169	    robot_ui_set_face(ROBOT_FACE_HAPPY);
170	    robot_ui_set_ai_reply("Hello! I am ZhiAi.\nHow can I help you?");
171	
172	    /* ===== 显示主菜单 ===== */
173	    touch_ui_show_menu(MENU_TYPE_MAIN);
174	
175	    printf("ZhiAi Companion started!\n");
176	
177	    /* 主循环 */
178	    while (1) {
179	        static int  net_tick = 0;
180	        static bool net_ok   = false;
181	
182	        lvgl_timer_handler();
183	
184	        /* 每 ~200ms 刷新一次状态栏上的网络状态。
185	         * LVGL 不是线程安全的，所以只在这个任务里改控件；network_task 那边
186	         * 只维护 mqtt_config.connected，由这里轮询。
187	         */
188	        if (++net_tick >= 40) {
189	            bool ok = mqtt_is_connected();
190	
191	            net_tick = 0;
192	            if (ok != net_ok) {
193	                net_ok = ok;
194	                robot_ui_set_net_status(ok ? "NET OK" : "NET --");
195	            }
196	        }
197	
198	        usleep(5000); // 5ms 刷新周期
199	    }
200	
201	    return 0;
202	}
