65	/* ==================== 编码 MQTT 剩余长度 ==================== */
66	static int mqtt_encode_remaining_length(uint8_t *buf, int length)
67	{
68	    int pos = 0;
69	    do {
70	        uint8_t byte = length % 128;
71	        length /= 128;
72	        if (length > 0) {
73	            byte |= 0x80;
74	        }
75	        buf[pos++] = byte;
76	    } while (length > 0);
77	    return pos;
78	}
