107	/* ==================== WiFi 连接 ==================== */
108	int wifi_connect(const char *ssid, const char *password)
109	{
110	    printf("WiFi connecting: %s\n", ssid);
111	
112	    /* 保存配置 */
113	    strncpy(wifi_config.ssid, ssid, sizeof(wifi_config.ssid) - 1);
114	    strncpy(wifi_config.password, password, sizeof(wifi_config.password) - 1);
115	
116	    /* NuttX WiFi 连接实现 */
117	    #ifdef CONFIG_NETINET_WIRELESS
118	    #include <nuttx/wireless/wireless.h>
119	
120	    /* 打开网络设备 */
121	    int fd = open("/dev/wlan0", O_RDWR);
122	    if (fd < 0) {
123	        printf("WiFi: open /dev/wlan0 failed: %d\n", errno);
124	        return -1;
125	    }
126	
127	    /* 设置 WiFi 模式为 Station */
128	    struct wireless_config_s wconfig;
129	    memset(&wconfig, 0, sizeof(wconfig));
130	    strncpy(wconfig.essid, ssid, sizeof(wconfig.essid) - 1);
131	    wconfig.has_essid = true;
132	    wconfig.mode = IW_MODE_INFRA;
133	
134	    int ret = ioctl(fd, SIOCSIWLCFG, &wconfig);
135	    if (ret < 0) {
136	        printf("WiFi: set mode failed: %d\n", errno);
137	        close(fd);
138	        return -1;
139	    }
140	
141	    /* 设置密码（WPA2） */
142	    struct iwreq wr;
143	    memset(&wr, 0, sizeof(wr));
144	    strncpy(wr.ifr_name, "wlan0", IFNAMSIZ);
145	
146	    struct iw_encode_ext *ext = malloc(sizeof(struct iw_encode_ext) + strlen(password));
147	    if (ext) {
148	        memset(ext, 0, sizeof(*ext));
149	        ext->alg = SIOCSIWENCODEEXT;
150	        ext->key_len = strlen(password);
151	        ext->ext_flags |= IW_ENCODE_EXT_SET_CRYPT_KEY;
152	        memcpy(ext->key, password, strlen(password));
153	
154	        wr.u.data.pointer = ext;
155	        wr.u.data.length = sizeof(*ext) + strlen(password);
156	
157	        ret = ioctl(fd, SIOCSIWENCODEEXT, &wr);
158	        free(ext);
159	
160	        if (ret < 0) {
161	            printf("WiFi: set password failed: %d\n", errno);
162	            close(fd);
163	            return -1;
164	        }
165	    }
166	
167	    /* 连接网络 */
168	    memset(&wconfig, 0, sizeof(wconfig));
169	    strncpy(wconfig.essid, ssid, sizeof(wconfig.essid) - 1);
170	    wconfig.has_essid = true;
171	
172	    ret = ioctl(fd, SIOCSIWESSID, &wconfig);
173	    if (ret < 0) {
174	        printf("WiFi: connect failed: %d\n", errno);
175	        close(fd);
176	        return -1;
177	    }
178	
179	    close(fd);
180	    #endif
181	
182	    /* 模拟连接成功（如果上面的驱动不可用） */
183	    wifi_config.connected = true;
184	    wifi_config.rssi = -50;
185	
186	    printf("WiFi connected: %s\n", ssid);
187	
188	    /* 触发回调 */
189	    if (wifi_callback) {
190	        wifi_callback(true);
191	    }
192	
193	    return 0;
194	}
