251	int mqtt_connect(const char *broker, uint16_t port,
252	                const char *client_id, const char *username, const char *password)
253	{
254	    printf("MQTT connecting: %s:%d\n", broker, port);
255	
256	    /* 保存配置 */
257	    strncpy(mqtt_config.broker, broker, sizeof(mqtt_config.broker) - 1);
258	    mqtt_config.port = port;
259	    strncpy(mqtt_config.client_id, client_id, sizeof(mqtt_config.client_id) - 1);
