262	    }
263	    if (password) {
264	        strncpy(mqtt_config.password, password, sizeof(mqtt_config.password) - 1);
265	    }
266	
267	    /* 创建 TCP 连接 */
268	    mqtt_socket = create_tcp_socket(broker, port);
269	    if (mqtt_socket < 0) {
270	        printf("TCP connect failed\n");
271	        return -1;
272	    }
273	
274	    /* 发送 MQTT CONNECT 包 */
275	    if (mqtt_send_connect() < 0) {
276	        printf("MQTT CONNECT failed\n");
277	        close(mqtt_socket);
278	        mqtt_socket = -1;
279	        return -1;
280	    }
281	
282	    mqtt_config.connected = true;
283	    printf("MQTT connected\n");
284	
285	    /* 订阅命令主题 */
286	    char topic[128];
287	    snprintf(topic, sizeof(topic), "zhi_ai/%s/command", client_id);
288	    mqtt_subscribe(topic, 1);
289	
290	    return 0;
291	}
