500	/* 发送 HTTP POST 请求 */
501	static int http_post(const char *url, const char *body)
502	{
503	    char host[128] = {0};
504	    char path[256] = {0};
505	    int port = 443;
506	
507	    /* 解析 URL */
508	    if (sscanf(url, "https://%127[^/]/%255s", host, path) != 2) {
509	        if (sscanf(url, "http://%127[^/]/%255s", host, path) != 2) {
510	            printf("http_post: invalid URL: %s\n", url);
511	            return -1;
512	        }
513	        port = 80;
514	    }
515	
516	    printf("http_post: host=%s, path=%s, port=%d\n", host, path, port);
517	
518	    /* 创建 TCP 连接 */
519	    int sockfd = create_tcp_socket(host, port);
520	    if (sockfd < 0) {
521	        printf("http_post: TCP connect failed\n");
522	        return -1;
523	    }
524	
525	    /* 构建 HTTP 请求 */
526	    char request[HTTP_BUFFER_SIZE];
527	    int body_len = strlen(body);
528	    snprintf(request, sizeof(request),
529	        "POST /%s HTTP/1.1\r\n"
530	        "Host: %s\r\n"
531	        "Content-Type: application/json; charset=utf-8\r\n"
532	        "Content-Length: %d\r\n"
533	        "Connection: close\r\n"
534	        "\r\n"
535	        "%s",
536	        path, host, body_len, body);
537	
538	    /* 发送请求 */
539	    int ret = send(sockfd, request, strlen(request), 0);
540	    if (ret < 0) {
541	        printf("http_post: send failed\n");
542	        close(sockfd);
543	        return -1;
544	    }
545	
546	    /* 接收响应 */
547	    char response[1024];
548	    int len = recv(sockfd, response, sizeof(response) - 1, 0);
549	    if (len > 0) {
550	        response[len] = '\0';
551	        printf("http_post: response=%s\n", response);
552	    }
553	
554	    close(sockfd);
555	    return 0;
556	}
