1097	/* 解析 MQTT 数据包 */
1098	static int mqtt_parse_packet(void)
1099	{
1100	    uint8_t buffer[1024];
1101	    int len = recv(mqtt_socket, buffer, sizeof(buffer), 0);
1102	    if (len <= 0) {
1103	        return -1;
1104	    }
1105	
1106	    uint8_t type = (buffer[0] >> 4) & 0x0F;
1107	
1108	    switch (type) {
1109	        case 0x0D:  // PINGRESP
1110	            printf("Received PINGRESP\n");
1111	            break;
1112	
1113	        case 0x03:  // PUBLISH
1114	            /* 解析主题和载荷 */
1115	            {
1116	                int pos = 1;
1117	
1118	                /* 跳过剩余长度编码 */
1119	                int remaining = 0;
1120	                int multiplier = 1;
1121	                do {
1122	                    remaining += (buffer[pos] & 0x7F) * multiplier;
1123	                    multiplier *= 128;
1124	                    pos++;
1125	                } while (buffer[pos - 1] & 0x80);
1126	
1127	                /* 解析主题 */
1128	                int topic_len = (buffer[pos] << 8) | buffer[pos + 1];
1129	                pos += 2;
1130	
1131	                char topic[128];
1132	                int copy_len = topic_len < (int)(sizeof(topic) - 1) ? topic_len : (int)(sizeof(topic) - 1);
1133	                memcpy(topic, &buffer[pos], copy_len);
1134	                topic[copy_len] = '\0';
1135	                pos += topic_len;
1136	
1137	                /* 解析载荷 */
1138	                char payload[1024];
1139	                int payload_len = len - pos;
1140	                if (payload_len > (int)(sizeof(payload) - 1)) {
1141	                    payload_len = (int)(sizeof(payload) - 1);
1142	                }
1143	                memcpy(payload, &buffer[pos], payload_len);
1144	                payload[payload_len] = '\0';
1145	
1146	                printf("Received: topic=%s, payload=%s\n", topic, payload);
1147	
1148	                /* 调用回调 */
1149	                if (mqtt_callback) {
1150	                    mqtt_callback(topic, payload);
1151	                }
1152	            }
1153	            break;
1154	
1155	        default:
1156	            printf("Unknown packet type: %d\n", type);
1157	            break;
1158	    }
1159	
1160	    return 0;
1161	}
