1197	/* ==================== 网络任务（后台运行） ==================== */
1198	void network_task(void *arg)
1199	{
1200	    printf("network_task started\n");
1201	
1202	    /* MQTT 重连节流 + broker 降级。每次尝试都要先做 DNS 解析再 connect：
1203	     * - 每 100ms 重来一次会把 CPU 和网络打满；
1204	     * - 一直 5 秒一次地锤公共 broker 会被限流（broker.emqx.io 就把我们
1205	     *   限了：连着 20 多分钟后它开始直接关连接、不给 CONNACK）。
1206	     * 所以前几次快一点（开机后尽快连上），失败多了就放慢到 30 秒；
1207	     * 连了 5 次还不行就换下一台 broker。
1208	     */
1209	    int mqtt_retry_tick = 0;
1210	    int mqtt_fails = 0;
1211	    int broker_idx = 0;
1212	    int broker_switches = 0;
1213	
1214	    while (1) {
1215	        /* 检查 WiFi 状态 */
1216	        if (!wifi_config.connected) {
1217	            /* 尝试重连 */
1218	            // TODO: 实现重连逻辑
1219	        }
1220	
1221	        /* 检查 MQTT 状态 */
1222	        if (wifi_config.connected && !mqtt_config.connected) {
1223	            if (--mqtt_retry_tick <= 0) {
1224	                /* 只有第一轮（还没换过 broker）才用 5 秒的快节奏，好在开机后
1225	                 * 尽快连上；一旦开始换 broker 说明网络/公共实例有问题，一律 30 秒，
1226	                 * 否则会变成"每台试 5 次、15 次一轮"地一直锤公共服务器。
1227	                 */
1228	                mqtt_retry_tick =
1229	                    (broker_switches == 0 && mqtt_fails < 5) ? 50 : 300;
1230	
1231	                /* 尝试连接 MQTT */
1232	                if (mqtt_connect(mqtt_config.broker, mqtt_config.port,
1233	                                 mqtt_config.client_id, mqtt_config.username,
1234	                                 mqtt_config.password) < 0) {
1235	                    mqtt_fails++;
1236	
1237	                    if (mqtt_fails >= 5 && MQTT_NBROKERS > 1) {
1238	                        /* 这台连不上（公共实例限流很常见），换下一台 */
1239	                        broker_idx = (broker_idx + 1) % MQTT_NBROKERS;
1240	                        broker_switches++;
1241	                        strncpy(mqtt_config.broker, g_mqtt_broker_list[broker_idx],
1242	                                sizeof(mqtt_config.broker) - 1);
1243	                        mqtt_config.broker[sizeof(mqtt_config.broker) - 1] = '\0';
1244	                        printf("MQTT broker 切换到 %s\n", mqtt_config.broker);
1245	                        mqtt_fails = 0;
1246	                    }
1247	                } else {
1248	                    mqtt_fails = 0;
1249	                }
1250	            }
1251	        }
1252	
1253	        /* 接收 MQTT 消息 */
1254	        if (mqtt_config.connected) {
1255	            mqtt_parse_packet();
1256	
1257	            /* 发送心跳 */
1258	            uint32_t now = (uint32_t)time(NULL) * 1000;
1259	            if (now - last_heartbeat_time >= HEARTBEAT_INTERVAL) {
1260	                report_heartbeat();
1261	                last_heartbeat_time = now;
1262	            }
1263	        }
1264	
1265	        usleep(100000);  // 100ms
1266	    }
1267	}
