void robot_ui_switch_view(ui_view_t view)
{
    switch (view) {
        case UI_VIEW_MAIN:
            lv_scr_load(scr_main);
            break;
        case UI_VIEW_ALARM:
            lv_scr_load(scr_alarm);
            break;
        default:
            break;
    }
}

/* ==================== 呼吸灯动画 ==================== */
static void anim_breathe_update(void *var, int32_t val)
{
    lv_obj_set_style_bg_opa((lv_obj_t *)var, (lv_opa_t)val, 0);
}

/* 启动呼吸灯动画 - 待机状态 */
void robot_ui_start_breathe_anim(void)
{
    lv_anim_init(&anim_breathe);
    lv_anim_set_var(&anim_breathe, scr_main);
    lv_anim_set_values(&anim_breathe, LV_OPA_COVER, LV_OPA_70);
    lv_anim_set_time(&anim_breathe, 2000);
    lv_anim_set_playback_time(&anim_breathe, 2000);
    lv_anim_set_repeat_count(&anim_breathe, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_exec_cb(&anim_breathe, anim_breathe_update);
    lv_anim_start(&anim_breathe);
}

/* 停止呼吸灯动画 */
void robot_ui_stop_breathe_anim(void)
{
    lv_anim_delete(scr_main, anim_breathe_update);
}

/* ==================== 聆听声波动画 ==================== */
static void anim_listening_update(void *var, int32_t val)
{
    lv_obj_set_style_text_opa((lv_obj_t *)var, (lv_opa_t)val, 0);
}

/* 聆听动画定时器回调 - 显示声波效果 */
static void listening_anim_timer_cb(lv_timer_t *timer)
{
    if (!anim_listening_active || lbl_listening == NULL) {
        return;
    }

    /* 声波图案循环 */
    static const char *wave_patterns[] = {
        "聆听中.",
        "聆听中..",
        "聆听中...",
        "聆听中 ..",
        "聆听中  .",
        "聆听中   ",
    };
    static int pattern_index = 0;

    lv_label_set_text(lbl_listening, wave_patterns[pattern_index]);
    pattern_index = (pattern_index + 1) % 6;
}

/* 启动聆听声波动画 */
void robot_ui_start_listening_anim(void)
{
    if (lbl_listening == NULL) return;

    anim_listening_active = true;
    listening_anim_phase = 0;

    /* 显示聆听标签 */
    lv_obj_clear_flag(lbl_listening, LV_OBJ_FLAG_HIDDEN);
    lv_label_set_text(lbl_listening, "聆听中...");

    /* 启动透明度动画 */
    lv_anim_init(&anim_listening);
    lv_anim_set_var(&anim_listening, lbl_listening);
    lv_anim_set_values(&anim_listening, LV_OPA_COVER, LV_OPA_50);
    lv_anim_set_time(&anim_listening, 800);
    lv_anim_set_playback_time(&anim_listening, 800);
    lv_anim_set_repeat_count(&anim_listening, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_exec_cb(&anim_listening, anim_listening_update);
    lv_anim_start(&anim_listening);

    /* 创建定时器更新声波文字 */
    static lv_timer_t *listening_timer = NULL;
    if (listening_timer == NULL) {
        listening_timer = lv_timer_create(listening_anim_timer_cb, 300, NULL);
    }
    lv_timer_ready(listening_timer);
}

/* 停止聆听声波动画 */
void robot_ui_stop_listening_anim(void)
{
    anim_listening_active = false;

    if (lbl_listening != NULL) {
        lv_obj_add_flag(lbl_listening, LV_OBJ_FLAG_HIDDEN);
        lv_anim_delete(lbl_listening, anim_listening_update);
    }
}

/* ==================== AI回复逐字显示 ==================== */
static void ai_reply_timer_cb(lv_timer_t *timer)
{
    if (ai_reply_index < (int)strlen(ai_reply_buffer)) {
        ai_reply_index++;
        lv_label_set_text_n(lbl_ai_reply, ai_reply_buffer, ai_reply_index);
    } else {
        /* 显示完成，停止定时器 */
        if (ai_reply_timer) {
            lv_timer_pause(ai_reply_timer);
        }
    }
}

/* 设置AI回复（逐字显示效果） */
void robot_ui_set_ai_reply_animated(const char *text)
{
    if (text == NULL || lbl_ai_reply == NULL) return;

    /* 复制文本到缓冲区 */
    strncpy(ai_reply_buffer, text, sizeof(ai_reply_buffer) - 1);
    ai_reply_buffer[sizeof(ai_reply_buffer) - 1] = '\0';
    ai_reply_index = 0;

    /* 清空显示 */
    lv_label_set_text(lbl_ai_reply, "");

    /* 启动或恢复定时器 */
    if (ai_reply_timer == NULL) {
        ai_reply_timer = lv_timer_create(ai_reply_timer_cb, 50, NULL);
    }
    lv_timer_reset(ai_reply_timer);
    lv_timer_resume(ai_reply_timer);
}

/* 停止逐字显示，直接显示全部 */
void robot_ui_set_ai_reply_immediate(const char *text)
{
    if (ai_reply_timer) {
        lv_timer_pause(ai_reply_timer);
    }
    robot_ui_set_ai_reply(text);
}

