    /* 停止之前的动画 */
    if (current_status == ROBOT_STATUS_LISTENING && status != ROBOT_STATUS_LISTENING) {
        robot_ui_stop_listening_anim();
    }
    if (current_status == ROBOT_STATUS_IDLE && status != ROBOT_STATUS_IDLE) {
        robot_ui_stop_breathe_anim();
    }

