110	/**
111	 * @brief  计算音频能量
112	 */
113	
114	static float sound_detect_calc_energy(const int16_t *data, size_t frames)
115	{
116	  if (data == NULL || frames == 0)
117	    {
118	      return 0;
119	    }
120	
121	  uint64_t sum = 0;
122	  for (size_t i = 0; i < frames; i++)
123	    {
124	      sum += (int64_t)data[i] * data[i];
125	    }
126	
127	  return (float)sum / frames;
128	}
