221	/**
222	 * @brief  执行模型推理 (模拟实现)
223	 */
224	
225	static int sound_detect_run_fallback(sound_detect_context_t *ctx,
226	                                     const int16_t *data, size_t frames)
227	{
228	  float energy;
229	  float rms;
230	  float peak = 0.0f;
231	  size_t crossings = 0;
232	
233	  if (ctx == NULL || data == NULL || frames == 0)
234	    {
235	      return -EINVAL;
236	    }
237	
238	  memset(ctx->results, 0, sizeof(ctx->results));
239	  energy = sound_detect_calc_energy(data, frames);
240	  rms = sqrtf(energy) / 32768.0f;
241	
242	  for (size_t i = 0; i < frames; i++)
243	    {
244	      float sample = fabsf((float)data[i]) / 32768.0f;
245	      if (sample > peak)
246	        {
247	          peak = sample;
248	        }
249	
250	      if (i > 0 && ((data[i - 1] < 0 && data[i] >= 0) ||
251	                    (data[i - 1] >= 0 && data[i] < 0)))
252	        {
253	          crossings++;
254	        }
255	    }
256	
257	  float zcr = (float)crossings / frames;
258	  ctx->results[SOUND_TYPE_NONE] = 0.95f;
259	
260	  /* 这是无模型演示后备：只用于联调，不代替训练模型或医疗判断。 */
261	
262	  if (peak > 0.75f && rms < 0.20f)
263	    {
264	      ctx->results[SOUND_TYPE_FALL] = 0.90f;
265	      ctx->results[SOUND_TYPE_NONE] = 0.10f;
266	    }
267	  else if (rms > 0.30f && zcr > 0.08f)
268	    {
269	      ctx->results[SOUND_TYPE_SCREAM] = 0.86f;
270	      ctx->results[SOUND_TYPE_NONE] = 0.14f;
271	    }
272	  else if (peak > 0.55f && rms < 0.30f)
273	    {
274	      ctx->results[SOUND_TYPE_KNOCK] = 0.78f;
275	      ctx->results[SOUND_TYPE_NONE] = 0.22f;
276	    }
277	
278	  return OK;
279	}
