281	static int sound_detect_run_model(sound_detect_context_t *ctx,
282	                                  const int16_t *data, size_t frames)
283	{
284	  int ret;
285	
286	  if (ctx == NULL || data == NULL || frames == 0)
287	    {
288	      return -EINVAL;
289	    }
290	
291	#ifdef CONFIG_HELLO_APP_EDGE_IMPULSE
292	  ret = edge_impulse_sound_classify(data, frames,
293	                                    ctx->results, SOUND_TYPE_MAX);
294	  if (ret < 0 && ret != -ENOSYS)
295	    {
296	      return ret;
297	    }
298	#else
299	  ret = -ENOSYS;
300	#endif
301	
302	  if (ret == -ENOSYS)
303	    {
304	      ret = sound_detect_run_fallback(ctx, data, frames);
305	      if (ret < 0)
306	        {
307	          return ret;
308	        }
309	    }
310	
311	  float max_score = 0;
312	  int max_idx = 0;
313	
314	  for (int i = 0; i < SOUND_TYPE_MAX; i++)
315	    {
316	      if (ctx->results[i] > max_score)
317	        {
318	          max_score = ctx->results[i];
319	          max_idx = i;
320	        }
321	    }
322	
323	  /* 检查是否超过阈值 */
324	
325	  if (max_score >= ctx->config.threshold && max_idx != SOUND_TYPE_NONE)
326	    {
327	      SOUND_DEBUG("模型检测: type=%s, score=%.2f",
328	                  g_type_names[max_idx], max_score);
329	
330	      /* 检查该类型是否启用 */
331	
332	      if (ctx->classes[max_idx].enabled)
333	        {
334	          sound_detect_add_result(ctx, max_idx, max_score);
335	          return OK;
336	        }
337	    }
338	
339	  return -ENODATA;
340	}
