353	  int ret;
354	
355	  SOUND_DEBUG("处理检测窗口: %zu 采样点", ctx->buffer_pos);
356	
357	  /* 检查能量是否足够 */
358	
359	  float energy = sound_detect_calc_energy(ctx->audio_buffer, ctx->buffer_pos);
360	  if (energy < DETECT_MIN_ENERGY)
361	    {
362	      SOUND_DEBUG("能量过低 (%.0f), 跳过检测", energy);
363	      return -ENODATA;
364	    }
365	
366	  /* 提取特征 */
367	
368	  ret = sound_detect_extract_mfcc(ctx->audio_buffer, ctx->buffer_pos,
369	                                  ctx->feature_buffer, MFCC_NUM_COEFFS);
370	  if (ret < 0)
371	    {
372	      SOUND_DEBUG("特征提取失败: %d", ret);
373	      return ret;
374	    }
375	
376	  /* 运行模型 */
377	
378	  ret = sound_detect_run_model(ctx, ctx->audio_buffer, ctx->buffer_pos);
379	  if (ret < 0 && ret != -ENODATA)
380	    {
381	      SOUND_DEBUG("模型推理失败: %d", ret);
382	      return ret;
383	    }
384	
385	  return OK;
386	}
