388	/**
389	 * @brief  检测线程
390	 */
391	
392	static void *sound_detect_thread(void *arg)
393	{
394	  sound_detect_context_t *ctx = (sound_detect_context_t *)arg;
395	
396	  SOUND_DEBUG("检测线程启动");
397	
398	  while (!ctx->detect_stop)
399	    {
400	      /* 检查是否有足够的数据 */
401	
402	      pthread_mutex_lock(&ctx->buffer_lock);
403	      if (ctx->buffer_pos >= SOUND_DETECT_FRAMES_PER_WINDOW)
404	        {
405	          ctx->state = DETECT_STATE_PROCESSING;
406	
407	          /* 处理检测窗口 */
408	
409	          sound_detect_process_window(ctx);
410	
411	          /* 移动缓冲区 */
412	
413	          size_t remaining = ctx->buffer_pos - SOUND_DETECT_FRAMES_PER_WINDOW;
414	          if (remaining > 0)
415	            {
416	              memmove(ctx->audio_buffer,
417	                      ctx->audio_buffer + SOUND_DETECT_FRAMES_PER_WINDOW,
418	                      remaining * sizeof(int16_t));
419	            }
420	
421	          ctx->buffer_pos = remaining;
422	          ctx->state = DETECT_STATE_COLLECTING;
423	        }
424	      pthread_mutex_unlock(&ctx->buffer_lock);
425	
426	      /* 休眠等待 */
427	
428	      usleep(10000); /* 10ms */
429	    }
430	
431	  SOUND_DEBUG("检测线程退出");
432	  return NULL;
433	}
