439	/**
440	 * @brief  初始化声音检测模块
441	 */
442	
443	int sound_detect_init(sound_detect_context_t *ctx,
444	                      const sound_detect_config_t *config)
445	{
446	  if (ctx == NULL)
447	    {
448	      return -EINVAL;
449	    }
450	
451	  SOUND_DEBUG("初始化声音检测模块");
452	
453	  /* 清零上下文 */
454	
455	  memset(ctx, 0, sizeof(sound_detect_context_t));
456	
457	  /* 设置默认配置 */
458	
459	  if (config != NULL)
460	    {
461	      memcpy(&ctx->config, config, sizeof(sound_detect_config_t));
462	    }
463	  else
464	    {
465	      ctx->config.mode = DETECT_MODE_REALTIME;
466	      ctx->config.threshold = SOUND_DETECT_THRESHOLD_DEFAULT;
467	      ctx->config.sample_rate = SOUND_DETECT_SAMPLE_RATE;
468	      ctx->config.frame_ms = SOUND_DETECT_FRAME_MS;
469	      ctx->config.enable_vad = true;
470	      ctx->config.enable_feedback = true;
471	    }
472	
473	  /* 分配音频缓冲区 */
474	
475	  ctx->buffer_size = SOUND_DETECT_FRAMES_PER_WINDOW * 2; /* 2秒缓冲 */
476	  ctx->audio_buffer = (int16_t *)malloc(ctx->buffer_size * sizeof(int16_t));
477	  if (ctx->audio_buffer == NULL)
478	    {
479	      SOUND_DEBUG("分配音频缓冲区失败");
480	      return -ENOMEM;
481	    }
482	
483	  /* 分配特征缓冲区 */
484	
485	  ctx->feature_size = MFCC_NUM_COEFFS;
486	  ctx->feature_buffer = (float *)malloc(ctx->feature_size * sizeof(float));
487	  if (ctx->feature_buffer == NULL)
488	    {
489	      SOUND_DEBUG("分配特征缓冲区失败");
490	      free(ctx->audio_buffer);
491	      return -ENOMEM;
492	    }
493	
494	  int ret = pthread_mutex_init(&ctx->buffer_lock, NULL);
495	  if (ret != 0)
496	    {
497	      free(ctx->feature_buffer);
498	      free(ctx->audio_buffer);
499	      return -ret;
500	    }
501	
502	  ctx->buffer_lock_valid = true;
503	
504	  /* 初始化默认分类 */
505	
506	  sound_detect_init_default_classes(ctx);
507	
508	  ctx->state = DETECT_STATE_IDLE;
509	  ctx->initialized = true;
510	
511	  SOUND_DEBUG("声音检测模块初始化完成");
512	  SOUND_DEBUG("  采样率: %d Hz", ctx->config.sample_rate);
513	  SOUND_DEBUG("  检测窗口: %d ms", SOUND_DETECT_WINDOW_MS);
514	  SOUND_DEBUG("  阈值: %.2f", ctx->config.threshold);
515	
516	  return OK;
517	}
