616	/**
617	 * @brief  从文件加载模型
618	 */
619	
620	int sound_detect_load_model_file(sound_detect_context_t *ctx,
621	                                 const char *model_path)
622	{
623	  if (ctx == NULL || model_path == NULL)
624	    {
625	      return -EINVAL;
626	    }
627	
628	  SOUND_DEBUG("从文件加载模型: %s", model_path);
629	
630	  FILE *file = fopen(model_path, "rb");
631	  if (file == NULL)
632	    {
633	      return -errno;
634	    }
635	
636	  if (fseek(file, 0, SEEK_END) != 0)
637	    {
638	      int error = errno;
639	      fclose(file);
640	      return -error;
641	    }
642	
643	  long length = ftell(file);
644	  if (length <= 0 || fseek(file, 0, SEEK_SET) != 0)
645	    {
646	      fclose(file);
647	      return -EINVAL;
648	    }
649	
650	  void *data = malloc((size_t)length);
651	  if (data == NULL)
652	    {
653	      fclose(file);
654	      return -ENOMEM;
655	    }
656	
657	  size_t read_size = fread(data, 1, (size_t)length, file);
658	  fclose(file);
659	  if (read_size != (size_t)length)
660	    {
661	      free(data);
662	      return -EIO;
663	    }
664	
665	  int ret = sound_detect_load_model(ctx, data, read_size);
666	  free(data);
667	  return ret;
668	}
