757	/**
758	 * @brief  输入音频数据进行检测
759	 */
760	
761	int sound_detect_feed(sound_detect_context_t *ctx,
762	                      const int16_t *data, size_t frames)
763	{
764	  if (ctx == NULL || data == NULL || frames == 0)
765	    {
766	      return -EINVAL;
767	    }
768	
769	  if (ctx->state != DETECT_STATE_COLLECTING)
770	    {
771	      return -EINVAL;
772	    }
773	
774	  if (frames > ctx->buffer_size)
775	    {
776	      data += frames - ctx->buffer_size;
777	      frames = ctx->buffer_size;
778	    }
779	
780	  pthread_mutex_lock(&ctx->buffer_lock);
781	
782	  /* 检查缓冲区空间 */
783	
784	  size_t free_space = ctx->buffer_size - ctx->buffer_pos;
785	  if (frames > free_space)
786	    {
787	      /* 缓冲区满，丢弃最旧的数据 */
788	
789	      size_t discard = frames - free_space;
790	      memmove(ctx->audio_buffer,
791	              ctx->audio_buffer + discard,
792	              (ctx->buffer_pos - discard) * sizeof(int16_t));
793	      ctx->buffer_pos -= discard;
794	    }
795	
796	  /* 复制数据到缓冲区 */
797	
798	  memcpy(ctx->audio_buffer + ctx->buffer_pos, data,
799	         frames * sizeof(int16_t));
800	  ctx->buffer_pos += frames;
801	
802	  ctx->stats.total_frames += frames;
803	
804	  pthread_mutex_unlock(&ctx->buffer_lock);
805	
806	  return OK;
807	}
