809	/**
810	 * @brief  执行单次检测
811	 */
812	
813	int sound_detect_once(sound_detect_context_t *ctx,
814	                      const int16_t *data, size_t frames,
815	                      sound_type_t *type, float *confidence)
816	{
817	  if (ctx == NULL || data == NULL || type == NULL || confidence == NULL)
818	    {
819	      return -EINVAL;
820	    }
821	
822	  *type = SOUND_TYPE_NONE;
823	  *confidence = 0;
824	
825	  /* 检查能量 */
826	
827	  float energy = sound_detect_calc_energy(data, frames);
828	  if (energy < DETECT_MIN_ENERGY)
829	    {
830	      return -ENODATA;
831	    }
832	
833	  /* 提取特征 */
834	
835	  float features[MFCC_NUM_COEFFS];
836	  int ret = sound_detect_extract_mfcc(data, frames,
837	                                      features, MFCC_NUM_COEFFS);
838	  if (ret < 0)
839	    {
840	      return ret;
841	    }
842	
843	  /* 运行模型 */
844	
845	  ret = sound_detect_run_model(ctx, data, frames);
846	  if (ret < 0 && ret != -ENODATA)
847	    {
848	      return ret;
849	    }
850	
851	  /* 找到最高分 */
852	
853	  float max_score = 0;
854	  int max_idx = 0;
855	
856	  for (int i = 0; i < SOUND_TYPE_MAX; i++)
857	    {
858	      if (ctx->results[i] > max_score)
859	        {
860	          max_score = ctx->results[i];
861	          max_idx = i;
862	        }
863	    }
864	
865	  if (max_score >= ctx->config.threshold && max_idx != SOUND_TYPE_NONE)
866	    {
867	      *type = max_idx;
868	      *confidence = max_score;
869	      return OK;
870	    }
871	
872	  return -ENODATA;
873	}
