558	/* 发送推送通知 */
559	int push_send_notification(const char *title, const char *content, const char *group)
560	{
561	    if (!push_config.enabled || push_config.push_key[0] == '\0') {
562	        printf("push_send_notification: push not enabled\n");
563	        return -1;
564	    }
565	
566	    char url[256] = {0};
567	    char body[HTTP_BUFFER_SIZE] = {0};
568	
569	    /* 构建 JSON 请求体 */
570	    cJSON *root = cJSON_CreateObject();
571	    cJSON_AddStringToObject(root, "title", title);
572	    cJSON_AddStringToObject(root, "body", content);
573	    if (group) {
