602	            break;
603	
604	        default:
605	            free(json_body);
606	            return -1;
607	    }
608	
609	    /* 发送 HTTP 请求 */
610	    int ret = http_post(url, json_body);
611	    free(json_body);
612	
613	    printf("push_send_notification: title=%s, ret=%d\n", title, ret);
614	    return ret;
615	}
