828	/* ==================== 内部函数实现 ==================== */
829	
830	/* 创建 TCP Socket */
831	static int create_tcp_socket(const char *host, uint16_t port)
832	{
833	    int sockfd;
834	    struct sockaddr_in server_addr;
835	
836	    /* 创建 socket */
837	    sockfd = socket(AF_INET, SOCK_STREAM, 0);
838	    if (sockfd < 0) {
839	        perror("socket");
840	        return -1;
841	    }
842	
843	    /* 设置服务器地址 */
844	    memset(&server_addr, 0, sizeof(server_addr));
845	    server_addr.sin_family = AF_INET;
846	    server_addr.sin_port = htons(port);
847	
848	    /* 解析主机名或 IP */
849	    struct hostent *he = gethostbyname(host);
850	    if (he) {
851	        memcpy(&server_addr.sin_addr, he->h_addr_list[0], he->h_length);
852	        printf("MQTT DNS: %s -> %s\n", host, inet_ntoa(server_addr.sin_addr));
853	    } else {
854	        server_addr.sin_addr.s_addr = inet_addr(host);
855	        printf("MQTT DNS: %s 解析失败, 当 IP 用\n", host);
856	    }
857	
858	    /* 连接服务器。
859	     *
860	     * 必须用「非阻塞 connect + select 超时」，不能直接用阻塞式 connect：
861	     * 对方如果不回 SYN（被限流、网络抖动、IP 过期），内核要等 SYN 重传耗尽
862	     * 才返回，在 NuttX 的配置下要 1~3 分钟。而 network_task 是单线程轮询，
863	     * 这一个 connect 就会把整个任务卡住——心跳不发、重连不做、串口一行日志
864	     * 都没有，看起来像"死机"。5 秒返回不了就当这次失败，下一轮重试。
865	     */
866	    if (fcntl(sockfd, F_SETFL, O_NONBLOCK) < 0) {
867	        perror("fcntl");
868	        close(sockfd);
869	        return -1;
870	    }
871	
872	    int cret = connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
873	    if (cret < 0 && errno != EINPROGRESS) {
874	        perror("connect");
875	        close(sockfd);
876	        return -1;
877	    }
878	
879	    if (cret < 0) {
880	        fd_set wset;
881	        struct timeval ctimeo;
882	        int cerr = 0;
883	        socklen_t elen = sizeof(cerr);
884	
885	        FD_ZERO(&wset);
886	        FD_SET(sockfd, &wset);
887	        ctimeo.tv_sec  = 5;
888	        ctimeo.tv_usec = 0;
889	
890	        if (select(sockfd + 1, NULL, &wset, NULL, &ctimeo) <= 0 ||
891	            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &cerr, &elen) < 0 ||
892	            cerr != 0) {
893	            printf("connect timeout/error: %s:%u\n", host, (unsigned)port);
894	            close(sockfd);
895	            return -1;
896	        }
897	    }
898	
899	    /* 保持非阻塞。
900	     *
901	     * network_task 是单线程轮询，任何一次阻塞都可能把整个循环卡死：
902	     * 心跳不发、重连不做、串口一行日志都没有，看起来像"死机"（实测过）。
903	     * 原来这里靠 SO_RCVTIMEO 让 recv 5 秒超时返回，但实测不可靠 ——
904	     * 循环会永久停在 recv 里。
905	     *
906	     * 非阻塞之后：没数据时 recv 立刻返回 -1，mqtt_parse_packet() 直接返回，
907	     * 循环继续跑，心跳照发、重连照做。
908	     */
909	    if (fcntl(sockfd, F_SETFL, O_NONBLOCK) < 0) {
910	        perror("fcntl");
911	        close(sockfd);
912	        return -1;
913	    }
914	
915	    return sockfd;
916	}
