918	/* 发送 MQTT CONNECT 包 */
919	static int mqtt_send_connect(void)
920	{
921	    uint8_t packet[512];
922	    int pos = 0;
923	
924	    /* 固定头: CONNECT = 0x10 */
925	    packet[pos++] = 0x10;
926	
927	    /* 可变头 */
928	    uint8_t variable_header[] = {
929	        0x00, 0x04, 'M', 'Q', 'T', 'T',  // 协议名
930	        0x04,  // 协议级别 (MQTT 3.1.1)
931	        0x06,  // 连接标志：下面按实际内容再补（见注释）
932	        0x00, 0x3C,  // 保持连接时间 60 秒
933	    };
934	
935	    /* 连接标志必须和 payload 里真实带了什么字段一致。
936	     *
937	     * 原来硬编码 0xC2（用户名+密码+遗嘱+清理会话），但下面只在 username /
938	     * password 非空时才往 payload 里追加对应字段 —— 两个都为空时，标志声称
939	     * "有用户名密码"、payload 里却没有，broker 判定报文非法，直接把连接关掉。
940	     * 表现就是「TCP 连得上，但永远收不到 CONNACK」。
941	     *
942	     * bit1=清理会话(0x02) bit2=遗嘱(0x04) bit7=用户名(0x80) bit6=密码(0x40)
943	     */
944	    if (mqtt_config.username[0]) {
945	        variable_header[7] |= 0x80;
946	    }
947	    if (mqtt_config.password[0]) {
948	        variable_header[7] |= 0x40;
949	    }
950	
951	    /* 构建载荷 */
952	    uint8_t payload[256];
953	    int payload_pos = 0;
954	
955	    /* 客户端 ID */
956	    int client_id_len = strlen(mqtt_config.client_id);
957	    payload[payload_pos++] = (client_id_len >> 8) & 0xFF;
958	    payload[payload_pos++] = client_id_len & 0xFF;
959	    memcpy(&payload[payload_pos], mqtt_config.client_id, client_id_len);
960	    payload_pos += client_id_len;
961	
962	    /* 遗嘱主题 */
963	    char will_topic[128];
964	    snprintf(will_topic, sizeof(will_topic), "zhi_ai/%s/status", mqtt_config.client_id);
965	    int will_topic_len = strlen(will_topic);
966	    payload[payload_pos++] = (will_topic_len >> 8) & 0xFF;
967	    payload[payload_pos++] = will_topic_len & 0xFF;
968	    memcpy(&payload[payload_pos], will_topic, will_topic_len);
969	    payload_pos += will_topic_len;
970	
971	    /* 遗嘱消息 */
972	    payload[payload_pos++] = 0x00;
973	    payload[payload_pos++] = 0x03;
974	    payload[payload_pos++] = 'O';
975	    payload[payload_pos++] = 'F';
976	    payload[payload_pos++] = 'F';
977	
978	    /* 用户名 */
979	    if (mqtt_config.username[0]) {
980	        int username_len = strlen(mqtt_config.username);
981	        payload[payload_pos++] = (username_len >> 8) & 0xFF;
982	        payload[payload_pos++] = username_len & 0xFF;
983	        memcpy(&payload[payload_pos], mqtt_config.username, username_len);
984	        payload_pos += username_len;
985	    }
986	
987	    /* 密码 */
988	    if (mqtt_config.password[0]) {
989	        int password_len = strlen(mqtt_config.password);
990	        payload[payload_pos++] = (password_len >> 8) & 0xFF;
991	        payload[payload_pos++] = password_len & 0xFF;
992	        memcpy(&payload[payload_pos], mqtt_config.password, password_len);
993	        payload_pos += password_len;
994	    }
995	
996	    /* 计算剩余长度并编码 */
997	    int remaining = sizeof(variable_header) + payload_pos;
998	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
999	
1000	    /* 复制可变头和载荷 */
1001	    memcpy(&packet[pos], variable_header, sizeof(variable_header));
1002	    pos += sizeof(variable_header);
1003	    memcpy(&packet[pos], payload, payload_pos);
1004	    pos += payload_pos;
1005	
1006	    /* 发送 */
1007	    return send(mqtt_socket, packet, pos, 0);
1008	}
