1010	/* 发送 MQTT SUBSCRIBE 包 */
1011	static int mqtt_send_subscribe(const char *topic, int qos)
1012	{
1013	    uint8_t packet[256];
1014	    int pos = 0;
1015	
1016	    /* 固定头: SUBSCRIBE = 0x82 */
1017	    packet[pos++] = 0x82;
1018	
1019	    /* 剩余长度 = 2(包ID) + 2(topic长度) + topic_len + 1(QoS) */
1020	    int topic_len = strlen(topic);
1021	    int remaining = 2 + 2 + topic_len + 1;
1022	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
1023	
1024	    /* 包 ID */
1025	    static uint16_t subscribe_id = 0;
1026	    subscribe_id++;
1027	    packet[pos++] = (subscribe_id >> 8) & 0xFF;
1028	    packet[pos++] = subscribe_id & 0xFF;
1029	
1030	    /* 主题过滤器 */
1031	    packet[pos++] = (topic_len >> 8) & 0xFF;
1032	    packet[pos++] = topic_len & 0xFF;
1033	    memcpy(&packet[pos], topic, topic_len);
1034	    pos += topic_len;
1035	
1036	    /* QoS */
1037	    packet[pos++] = qos;
1038	
1039	    return send(mqtt_socket, packet, pos, 0);
1040	}
1041	
1042	/* 发送 MQTT PUBLISH 包 */
1043	static int mqtt_send_publish(const char *topic, const char *payload, int qos, bool retain)
1044	{
1045	    uint8_t packet[1024];
1046	    int pos = 0;
1047	
1048	    /* 固定头 */
1049	    uint8_t type = 0x30;  // PUBLISH
1050	    if (qos == 1) type |= 0x02;
1051	    if (qos == 2) type |= 0x04;
1052	    if (retain) type |= 0x01;
1053	    packet[pos++] = type;
1054	
1055	    /* 剩余长度 = 2 + topic_len + payload_len [+ 2(包ID)] */
1056	    int topic_len = strlen(topic);
1057	    int payload_len = strlen(payload);
1058	    int remaining = 2 + topic_len + payload_len;
1059	    if (qos > 0) remaining += 2;
1060	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
1061	
1062	    /* 主题名 */
1063	    packet[pos++] = (topic_len >> 8) & 0xFF;
1064	    packet[pos++] = topic_len & 0xFF;
1065	    memcpy(&packet[pos], topic, topic_len);
1066	    pos += topic_len;
1067	
1068	    /* 包 ID（QoS 1 或 2 时） */
1069	    if (qos > 0) {
1070	        static uint16_t packet_id = 0;
1071	        packet_id++;
1072	        packet[pos++] = (packet_id >> 8) & 0xFF;
1073	        packet[pos++] = packet_id & 0xFF;
1074	    }
1075	
1076	    /* 载荷 */
1077	    memcpy(&packet[pos], payload, payload_len);
1078	    pos += payload_len;
1079	
1080	    return send(mqtt_socket, packet, pos, 0);
1081	}
