429	  deadline.tv_sec += LLM_HTTP_TIMEOUT_MS / 1000;
430	  deadline.tv_nsec += (LLM_HTTP_TIMEOUT_MS % 1000) * 1000000L;
431	  if (deadline.tv_nsec >= 1000000000L)
432	    {
433	      deadline.tv_sec++;
434	      deadline.tv_nsec -= 1000000000L;
435	    }
436	
437	  do
438	    {
439	      ret = sem_timedwait(&ctx->backend_sem, &deadline);
440	    }
441	  while (ret < 0 && errno == EINTR && !ctx->request_cancel);
442	
443	  if (ret < 0)
444	    {
445	      return errno == ETIMEDOUT ? -ETIMEDOUT : -errno;
446	    }
447	  if (ctx->backend_reply_status < 0)
448	    {
449	      return ctx->backend_reply_status;
450	    }
451	  if (ctx->backend_reply[0] == '\0')
452	    {
453	      return -ENODATA;
454	    }
455	
456	  strncpy(response, ctx->backend_reply, response_size - 1);
457	  response[response_size - 1] = '\0';
458	  return OK;
459	}
460	#endif
