636	/**
637	 * @brief  发送到API
638	 */
639	
640	static int llm_send_to_api(llm_context_t *ctx,
641	                           const char *text,
642	                           llm_stream_cb_t stream_cb,
643	                           llm_complete_cb_t complete_cb,
644	                           void *user_data)
645	{
646	  if (ctx == NULL || text == NULL)
647	    {
648	      return -EINVAL;
649	    }
650	
651	  int ret;
652	  char response_content[LLM_MAX_OUTPUT_LENGTH];
653	
654	#ifdef CONFIG_HELLO_APP_LLM_AI_AGENT
655	  ret = llm_do_ai_agent_request(ctx, text, response_content,
656	                                sizeof(response_content));
657	#else
658	  char request_json[4096];
659	
660	  ret = llm_build_request_json(ctx, text, request_json, sizeof(request_json));
661	  if (ret < 0)
662	    {
663	      LLM_DEBUG("构建请求JSON失败: %d", ret);
664	      return ret;
665	    }
666	
667	  LLM_DEBUG("请求JSON:\n%s", request_json);
668	
669	  /* 发送HTTP请求 */
670	
671	  llm_response_t http_response;
672	  memset(&http_response, 0, sizeof(http_response));
673	
674	  ret = llm_do_http_request(ctx, ctx->config.api_url,
675	                            ctx->config.api_key,
676	                            request_json, &http_response);
677	  if (ret < 0)
678	    {
679	      LLM_DEBUG("HTTP请求失败: %d", ret);
680	
681	      if (complete_cb)
682	        {
683	          complete_cb(NULL, ret, user_data);
684	        }
685	
686	      return ret;
687	    }
688	
689	  /* 检查HTTP状态码 */
690	
691	  if (http_response.status_code != 200)
692	    {
693	      LLM_DEBUG("HTTP错误: status=%d", http_response.status_code);
694	
695	      if (http_response.body)
696	        {
697	          free(http_response.body);
698	        }
699	
700	      if (complete_cb)
701	        {
702	          complete_cb(NULL, -http_response.status_code, user_data);
703	        }
704	
705	      return -http_response.status_code;
706	    }
707	
708	  /* 解析响应 */
709	
710	  ret = llm_parse_api_response(ctx, &http_response,
711	                               response_content, sizeof(response_content));
712	
713	  if (http_response.body)
714	    {
715	      free(http_response.body);
716	    }
717	
718	  if (ret < 0)
719	    {
720	      LLM_DEBUG("解析响应失败: %d", ret);
721	
722	      if (complete_cb)
723	        {
724	          complete_cb(NULL, ret, user_data);
725	        }
726	
727	      return ret;
728	    }
729	#endif
730	
731	  if (ret < 0)
732	    {
733	      if (complete_cb != NULL)
734	        {
735	          complete_cb(NULL, ret, user_data);
736	        }
737	
738	      return ret;
739	    }
740	
741	  if (ctx->request_cancel)
742	    {
743	      return -ECANCELED;
744	    }
745	
746	  /* 添加到历史 */
747	
748	  if (ctx->config.enable_history)
749	    {
750	      llm_add_to_history(ctx, LLM_ROLE_USER, text);
751	      llm_add_to_history(ctx, LLM_ROLE_ASSISTANT, response_content);
752	    }
753	
754	  if (stream_cb != NULL)
755	    {
756	      stream_cb(response_content, user_data);
757	    }
758	
759	  /* 调用完成回调 */
760	
761	  if (complete_cb)
762	    {
763	      complete_cb(response_content, 0, user_data);
764	    }
765	
766	  LLM_DEBUG("AI回复: %s", response_content);
767	
768	  return OK;
769	}
