771	/**
772	 * @brief  请求线程函数
773	 */
774	
775	static void *llm_request_thread(void *arg)
776	{
777	  llm_context_t *ctx = (llm_context_t *)arg;
778	
779	  LLM_DEBUG("请求线程启动");
780	
781	  /* 发送到API */
782	
783	  int ret = llm_send_to_api(ctx,
784	                            ctx->current_request.text,
785	                            ctx->current_request.stream_cb,
786	                            ctx->current_request.complete_cb,
787	                            ctx->current_request.user_data);
788	
789	  if (ret < 0)
790	    {
791	      ctx->state = LLM_STATE_ERROR;
792	      LLM_DEBUG("请求失败: %d", ret);
793	    }
794	  else
795	    {
796	      ctx->state = LLM_STATE_DONE;
797	    }
798	
799	  LLM_DEBUG("请求线程退出");
800	
801	  return NULL;
802	}
