958	/**
959	 * @brief  发送文本请求
960	 */
961	
962	int llm_send_text(llm_context_t *ctx,
963	                  const char *text,
964	                  llm_stream_cb_t stream_cb,
965	                  llm_complete_cb_t complete_cb,
966	                  void *user_data)
967	{
968	  if (ctx == NULL || !ctx->initialized || text == NULL)
969	    {
970	      return -EINVAL;
971	    }
972	
973	  if (ctx->state == LLM_STATE_REQUESTING ||
974	      ctx->state == LLM_STATE_STREAMING)
975	    {
976	      LLM_DEBUG("已有请求在处理中");
977	      return -EBUSY;
978	    }
979	
980	  size_t text_len = strlen(text);
981	  if (text_len == 0 || text_len >= ctx->request_buf_size)
982	    {
983	      LLM_DEBUG("输入文本为空");
984	      return -EINVAL;
985	    }
986	
987	  LLM_DEBUG("发送文本请求: len=%zu", text_len);
988	
989	  if (ctx->request_thread_valid)
990	    {
991	      pthread_join(ctx->request_thread, NULL);
992	      ctx->request_thread_valid = false;
993	    }
994	
995	  /* 保存请求参数 */
996	
997	  ctx->current_request.type = LLM_REQUEST_TEXT;
998	  memcpy(ctx->request_buf, text, text_len + 1);
999	  ctx->current_request.text = ctx->request_buf;
1000	  ctx->current_request.stream_cb = stream_cb;
1001	  ctx->current_request.complete_cb = complete_cb;
1002	  ctx->current_request.user_data = user_data;
1003	  ctx->request_cancel = false;
1004	  ctx->state = LLM_STATE_REQUESTING;
1005	
1006	  /* 启动请求线程 */
1007	
1008	  int ret = pthread_create(&ctx->request_thread, NULL,
1009	                           llm_request_thread, ctx);
1010	  if (ret != 0)
1011	    {
1012	      LLM_DEBUG("创建请求线程失败: %d", ret);
1013	      ctx->state = LLM_STATE_ERROR;
1014	      return -ret;
1015	    }
1016	
1017	  ctx->request_thread_valid = true;
1018	
1019	  return OK;
1020	}
