1144	  /* 获取最后一条助手消息 */
1145	
1146	  int idx = (ctx->history.tail - 1 + LLM_MAX_HISTORY_SIZE) %
1147	            LLM_MAX_HISTORY_SIZE;
1148	
1149	  for (int i = 0; i < ctx->history.count; i++)
1150	    {
1151	      if (ctx->history.messages[idx].role == LLM_ROLE_ASSISTANT)
1152	        {
1153	          return ctx->history.messages[idx].content;
1154	        }
1155	      idx = (idx - 1 + LLM_MAX_HISTORY_SIZE) % LLM_MAX_HISTORY_SIZE;
1156	    }
1157	
1158	  return NULL;
1159	}
