115	            robot_ui_set_face(ROBOT_FACE_THINKING);
116	        } else if (strcmp(param, "sleepy") == 0) {
117	            robot_ui_set_face(ROBOT_FACE_SLEEPY);
118	        } else if (strcmp(param, "surprised") == 0) {
119	            robot_ui_set_face(ROBOT_FACE_SURPRISED);
120	        } else if (strcmp(param, "worried") == 0) {
121	            robot_ui_set_face(ROBOT_FACE_WORRIED);
122	        }
123	    }
124	    else if (strcmp(action, "send_text") == 0) {
125	        /* 发送文本到 AI */
126	        if (g_ai_initialized) {
127	            robot_ui_set_status(ROBOT_STATUS_LISTENING);
128	            robot_ui_set_face(ROBOT_FACE_THINKING);
129	            llm_send_request(&g_llm_ctx, param, NULL);
130	        }
131	    }
