204	/**
205	 * 处理来自 MQTT 的消息
206	 * 解析命令并转发给 AI 命令处理函数
207	 */
208	static void on_mqtt_message_received(const char *topic, const char *payload)
209	{
210	    printf("MQTT received: topic=%s\n", topic);
211	
212	    /* 解析 JSON 命令 */
213	    cJSON *root = cJSON_Parse(payload);
214	    if (!root) {
215	        printf("JSON parse failed\n");
216	        return;
217	    }
218	
219	    cJSON *action = cJSON_GetObjectItem(root, "action");
220	    cJSON *param = cJSON_GetObjectItem(root, "param");
221	
222	    if (action && action->valuestring) {
223	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
224	        on_ai_command_received(action->valuestring, param_str);
225	    }
226	
227	    cJSON_Delete(root);
228	}
