230	/* 主函数 */
231	int main(int argc, char *argv[])
232	{
233	    printf("ZhiAi Companion starting...\n");
234	
235	    /* ===== 初始化 LVGL 与显示设备（必须在 UI 创建之前） ===== */
236	    lv_init();
237	    lv_nuttx_dsc_t lv_info = {0};
238	    lv_nuttx_result_t lv_result = {0};
239	    lv_nuttx_dsc_init(&lv_info);
240	    lv_nuttx_init(&lv_info, &lv_result);
241	    if (lv_result.disp == NULL)
242	    {
243	        printf("LVGL display init failed!\n");
244	        return 1;
245	    }
246	
247	    /* ===== 初始化网络通信 ===== */
248	    network_comm_init();
249	
250	    /* ===== 连接 WiFi ===== */
251	    wifi_connect("魔王城", "sjmbahczdszjj");
252	
253	    /* ===== 启动网络后台任务 =====
254	     * 负责 MQTT 连接 broker.emqx.io:1883、收消息、发心跳。
255	     * network_task() 一直存在但从来没被创建过，所以 MQTT 一次都没连上过。
256	     * 它自己会轮询 wifi_config.connected，所以放在 wifi_connect() 之后创建。
257	     */
258	    if (task_create("net_task", 100, 12288, (main_t)network_task, NULL) < 0) {
259	        printf("net_task create failed\n");
260	    }
261	
262	    /* ===== 初始化手机推送服务 ===== */
263	    /* PushPlus (Android 微信推送) */
264	    push_init(PUSH_SERVICE_PUSHPLUS, "1043ad84f9ba4dbb921756173d36277a");
265	    /* Bark (iPad iOS 推送) */
266	    push_init(PUSH_SERVICE_BARK, "726d1da9c292efcf947a85897c38310f6200a45c60ec8683813ae4d06fe67be9");
267	
268	    /* ===== 注册回调函数 ===== */
269	    network_set_mqtt_callback(on_mqtt_message_received);
270	    network_set_ai_command_callback(on_ai_command_received);
271	
272	    /* ===== 初始化 AI 模块 (成员二) ===== */
273	    printf("Initializing AI modules...\n");
274	
275	    /* 初始化状态机 */
276	    if (sm_init(&g_sm_ctx) == 0) {
277	        printf("State machine initialized\n");
278	    }
279	
280	    /* 初始化音频模块 */
281	    audio_config_t audio_config = {
282	        .sample_rate = AUDIO_RATE_16K,
283	        .channels = AUDIO_CH_MONO,
284	        .bits_per_sample = 16
285	    };
286	    if (audio_init(&g_audio_ctx, &audio_config) == 0) {
287	        printf("Audio module initialized\n");
288	        /* 启用 VAD 检测 */
289	        audio_vad_enable(&g_audio_ctx, vad_callback, NULL);
290	    }
291	
292	    /* 初始化 LLM 模块 */
293	    if (llm_init(&g_llm_ctx, NULL) == 0) {
294	        printf("LLM module initialized\n");
295	    }
296	
297	    /* 初始化声音检测 */
298	    if (sound_detect_init(&g_sound_ctx) == 0) {
299	        printf("Sound detect initialized\n");
300	        /* 注册报警回调 */
301	        sound_detect_set_alarm_callback(&g_sound_ctx, sound_alarm_callback, NULL);
302	    }
303	
304	    /* 初始化主动关怀 */
305	    if (care_init(&g_care_ctx) == 0) {
306	        printf("Care module initialized\n");
307	        /* 注册提醒回调 */
308	        care_set_remind_callback(&g_care_ctx, care_remind_callback, NULL);
309	    }
310	
311	    g_ai_initialized = true;
312	    printf("AI modules initialization done\n");
313	
314	    /* ===== 初始化机器人 UI（先创建主屏并 lv_scr_load，成为活动屏） ===== */
315	    robot_ui_init();
316	
317	    /* ===== 初始化触摸交互 UI（须在活动屏 = 主屏之后, 菜单才可见） ===== */
318	    touch_ui_init();
319	
320	    /* ===== 添加默认提醒 ===== */
321	    touch_ui_add_reminder("吃药", "08:00");
322	    touch_ui_add_reminder("喝水", "10:00");
323	    touch_ui_add_reminder("散步", "16:00");
324	
325	    /* ===== 设置初始状态 ===== */
326	    robot_ui_set_status(ROBOT_STATUS_IDLE);
327	    robot_ui_set_face(ROBOT_FACE_HAPPY);
328	    robot_ui_set_ai_reply("你好！我是智爱陪伴\n有什么可以帮你的吗？");
329	
330	    /* ===== 显示主菜单 ===== */
331	    touch_ui_show_menu(MENU_TYPE_MAIN);
332	
333	    printf("ZhiAi Companion started!\n");
334	
335	    /* 主循环 */
336	    while (1) {
337	        static int  net_tick = 0;
338	        static bool net_ok   = false;
339	
340	        lvgl_timer_handler();
341	
342	        /* 每 ~200ms 刷新一次状态栏上的网络状态。
343	         * LVGL 不是线程安全的，所以只在这个任务里改控件；network_task 那边
344	         * 只维护 mqtt_config.connected，由这里轮询。
345	         */
346	        if (++net_tick >= 40) {
347	            bool ok = mqtt_is_connected();
348	
349	            net_tick = 0;
350	            if (ok != net_ok) {
351	                net_ok = ok;
352	                robot_ui_set_net_status(ok ? "NET OK" : "NET --");
353	            }
354	        }
355	
356	        /* 运行 AI 模块 */
357	        if (g_ai_initialized) {
358	            sm_run(&g_sm_ctx);
359	        }
360	        }
361	
362	        usleep(5000); // 5ms 刷新周期
363	    }
364	
365	    return 0;
366	}
