502	/* ==================== 关闭报警 ==================== */
503	void robot_ui_close_alarm(void)
504	{
505	    /* 停止闪烁动画 */
506	    /* v9 语义: lv_anim_delete(var, exec_cb) 第一个参数是动画绑定的对象
507	     * (anim_blink.var == scr_alarm), 不是 lv_anim_t 结构体地址 */
