207	 * 处理来自 MQTT 的消息
208	 * 解析命令并转发给 AI 命令处理函数
209	 */
210	static void on_mqtt_message_received(const char *topic, const char *payload)
211	{
212	    printf("MQTT received: topic=%s\n", topic);
213	
214	    /* 解析 JSON 命令 */
215	    cJSON *root = cJSON_Parse(payload);
216	    if (!root) {
217	        printf("JSON parse failed\n");
218	        return;
219	    }
220	
221	    cJSON *action = cJSON_GetObjectItem(root, "action");
222	    cJSON *param = cJSON_GetObjectItem(root, "param");
223	
224	    if (action && action->valuestring) {
225	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
226	        on_ai_command_received(action->valuestring, param_str);
227	    }
228	
229	    cJSON_Delete(root);
230	}
