141	/* ==================== 初始化触摸交互 UI ==================== */
142	void touch_ui_init(void)
143	{
144	    /* 初始化样式 */
145	    init_elder_styles();
146	
147	    /* 初始化提醒列表 */
148	    memset(reminders, 0, sizeof(reminders));
149	    reminder_count = 0;
150	
151	    /* 面板句柄复位: NuttX builtin 应用重新运行时 .bss 不清零,
152	     * 若残留上一次运行的面板指针, 之后 lv_obj_del() 会去删除已
153	     * 失效的 LVGL 对象而导致 hardfault */
154	    menu_panel = NULL;
155	    setting_panel = NULL;
156	    reminder_panel = NULL;
157	
158	    /* 获取当前活动屏幕 */
159	    current_screen = lv_scr_act();
160	    lv_obj_add_style(current_screen, &style_elder, 0);
161	
162	    printf("touch_ui init done\n");
163	}
