165	/* ==================== 显示菜单 ==================== */
166	void touch_ui_show_menu(menu_type_t type)
167	{
168	    /* 清除所有旧面板. 注意 setting_panel 是活动屏的兄弟节点,
169	     * 不挂在 menu_panel 下, 只删 menu_panel 会遗留旧设置面板,
170	     * 导致新旧面板重叠且整棵对象树泄漏 */
171	    if (menu_panel) {
172	        lv_obj_del(menu_panel);
173	        menu_panel = NULL;
174	    }
175	    if (setting_panel) {
176	        lv_obj_del(setting_panel);
177	        setting_panel = NULL;
178	    }
179	    if (reminder_panel) {
180	        lv_obj_del(reminder_panel);
181	        reminder_panel = NULL;
182	    }
183	
184	    /* 创建菜单面板 */
185	    create_menu_panel(type);
186	}
187	
188	/* ==================== 隐藏菜单 ==================== */
189	void touch_ui_hide_menu(void)
190	{
191	    if (menu_panel) {
192	        lv_obj_del(menu_panel);
193	        menu_panel = NULL;
194	    }
195	}
