198	void touch_ui_go_back(void)
199	{
200	    /* 隐藏所有面板 */
201	    touch_ui_hide_menu();
202	
203	    if (setting_panel) {
204	        lv_obj_del(setting_panel);
205	        setting_panel = NULL;
206	    }
207	
208	    if (reminder_panel) {
209	        lv_obj_del(reminder_panel);
210	        reminder_panel = NULL;
211	    }
212	
213	    /* 播放返回音效 */
214	    touch_ui_play_sound("back");
215	}
