217	/* ==================== 创建菜单面板 ==================== */
218	static void create_menu_panel(menu_type_t type)
219	{
220	    /* 菜单容器 */
221	    menu_panel = lv_obj_create(current_screen);
222	    lv_obj_set_size(menu_panel, LV_PCT(95), LV_PCT(85));
223	    lv_obj_align(menu_panel, LV_ALIGN_CENTER, 0, 0);
224	    lv_obj_add_style(menu_panel, &style_elder, 0);
225	    lv_obj_set_flex_flow(menu_panel, LV_FLEX_FLOW_COLUMN);
226	    lv_obj_set_flex_align(menu_panel, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
227	    lv_obj_set_style_pad_all(menu_panel, 20, 0);
228	    lv_obj_set_style_pad_row(menu_panel, 15, 0);
229	
230	    /* 标题 */
231	    lv_obj_t *title = lv_label_create(menu_panel);
232	    switch (type) {
233	        case MENU_TYPE_MAIN:
234	            lv_label_set_text(title, "[主] 主菜单");
235	            break;
236	        case MENU_TYPE_REMIND:
237	            lv_label_set_text(title, "[提] 提醒");
238	            break;
239	        case MENU_TYPE_SETTING:
240	            lv_label_set_text(title, "[设] 设置");
241	            break;
242	        case MENU_TYPE_ABOUT:
243	            lv_label_set_text(title, "[?] 关于");
244	            break;
245	        default:
246	            lv_label_set_text(title, "菜单");
247	            break;
248	    }
249	    lv_obj_set_style_text_font(title, &lv_font_custom_28, 0);
250	    lv_obj_set_style_text_color(title, lv_color_hex(0xFFEB3B), 0);
251	    lv_obj_set_style_pad_bottom(title, 20, 0);
252	
253	    /* 根据菜单类型创建内容 */
254	    switch (type) {
255	        case MENU_TYPE_MAIN:
256	            create_menu_item(menu_panel, "[语] 语音聊天", "与机器人对话", 0);
257	            create_menu_item(menu_panel, "[提] 查看提醒", "查看今日提醒", 1);
258	            create_menu_item(menu_panel, "[设] 设置", "音量、亮度等", 2);
259	            create_menu_item(menu_panel, "[急] 紧急呼叫", "联系家人", 3);
260	            create_menu_item(menu_panel, "[?] 关于", "版本信息", 4);
261	            break;
262	
263	        case MENU_TYPE_REMIND:
264	            create_reminder_list_items(menu_panel);
265	            break;
266	
267	        case MENU_TYPE_SETTING:
268	            create_setting_panel();
269	            break;
270	
271	        case MENU_TYPE_ABOUT:
272	            create_about_info(menu_panel);
273	            break;
274	
275	        default:
276	            break;
277	    }
278	
279	    /* 返回按钮 */
280	    create_back_button(menu_panel);
281	}
