406	static void create_slider_setting(lv_obj_t *parent, const char *title,
407	                                 int value, int index)
408	{
409	    /* 容器 */
410	    lv_obj_t *container = lv_obj_create(parent);
411	    lv_obj_set_size(container, LV_PCT(100), LV_SIZE_CONTENT);
412	    lv_obj_set_style_bg_opa(container, LV_OPA_TRANSP, 0);
413	    lv_obj_set_style_border_width(container, 0, 0);
414	    lv_obj_set_flex_flow(container, LV_FLEX_FLOW_COLUMN);
415	    lv_obj_set_style_pad_all(container, 0, 0);
416	
417	    /* 标题行 */
418	    lv_obj_t *title_row = lv_obj_create(container);
419	    lv_obj_set_size(title_row, LV_PCT(100), 40);
420	    lv_obj_set_style_bg_opa(title_row, LV_OPA_TRANSP, 0);
421	    lv_obj_set_style_border_width(title_row, 0, 0);
422	    lv_obj_set_flex_flow(title_row, LV_FLEX_FLOW_ROW);
