952	/**
953	 * 更新关怀确认状态显示
954	 * 可从任意线程调用，内部通过 lv_async_call 投递到 LVGL 线程
955	 */
956	static void update_checkin_state_async(void *state_ptr)
957	{
958	    touch_checkin_state_t state = (touch_checkin_state_t)(intptr_t)state_ptr;
959	
960	    if (!checkin_status_lbl) return;
961	
962	    switch (state) {
963	        case TOUCH_CHECKIN_WAITING:
964	            lv_label_set_text(checkin_status_lbl, "等待确认");
965	            lv_obj_set_style_text_color(checkin_status_lbl,
966	                                        lv_color_hex(0x4CAF50), 0);
967	            /* 重新启用按钮（新任务） */
968	            if (checkin_btn_fine) lv_obj_clear_state(checkin_btn_fine, LV_STATE_DISABLED);
969	            if (checkin_btn_help) lv_obj_clear_state(checkin_btn_help, LV_STATE_DISABLED);
970	            checkin_confirmed = false;
971	            break;
972	
973	        case TOUCH_CHECKIN_SENDING:
974	            lv_label_set_text(checkin_status_lbl, "正在通知...");
975	            lv_obj_set_style_text_color(checkin_status_lbl,
976	                                        lv_color_hex(0xFFC107), 0);
977	            break;
978	
979	        case TOUCH_CHECKIN_SENT:
980	            lv_label_set_text(checkin_status_lbl, "通知成功 ✓");
981	            lv_obj_set_style_text_color(checkin_status_lbl,
982	                                        lv_color_hex(0x4CAF50), 0);
983	            /* 成功后延迟关闭面板 */
984	            /* TODO: 可以加一个 2 秒定时器自动关闭 */
985	            break;
986	
987	        case TOUCH_CHECKIN_FAILED:
988	            lv_label_set_text(checkin_status_lbl, "通知失败，请重试");
989	            lv_obj_set_style_text_color(checkin_status_lbl,
990	                                        lv_color_hex(0xF44336), 0);
991	            /* 失败时重新启用按钮让用户重试 */
992	            if (checkin_btn_fine) lv_obj_clear_state(checkin_btn_fine, LV_STATE_DISABLED);
993	            if (checkin_btn_help) lv_obj_clear_state(checkin_btn_help, LV_STATE_DISABLED);
994	            checkin_confirmed = false;
995	            break;
996	
997	        default:
998	            break;
999	    }
1000	}
1001	
1002	void touch_ui_update_checkin_state(touch_checkin_state_t state)
1003	{
1004	    /* 投递到 LVGL 线程执行，避免跨线程操作控件 */
1005	    lv_async_call(update_checkin_state_async, (void *)(intptr_t)state);
1006	}
