297	/* ==================== 按钮事件处理 ==================== */
298	static void btn_event_handler(lv_event_t *e)
299	{
300	    lv_event_code_t code = lv_event_get_code(e);
301	    ui_view_t view = (ui_view_t)lv_event_get_user_data(e);
302	
303	    if (code == LV_EVENT_CLICKED) {
304	        switch (view) {
305	            case UI_VIEW_REMIND:
306	                robot_ui_show_reminder("Health", "Time to take medicine!");
307	                break;
308	            case UI_VIEW_SETTING:
