559	int push_send_notification(const char *title, const char *content, const char *group)
560	{
561	    if (!push_config.enabled || push_config.push_key[0] == '\0') {
562	        printf("push_send_notification: push not enabled\n");
563	        return -1;
564	    }
565	
566	    char url[256] = {0};
567	    char body[HTTP_BUFFER_SIZE] = {0};
568	
569	    /* 构建 JSON 请求体 */
570	    cJSON *root = cJSON_CreateObject();
571	    cJSON_AddStringToObject(root, "title", title);
572	    cJSON_AddStringToObject(root, "body", content);
573	    if (group) {
574	        cJSON_AddStringToObject(root, "group", group);
575	    }
576	    cJSON_AddStringToObject(root, "device", "ZhiAi-Companion");
577	
578	    char *json_body = cJSON_PrintUnformatted(root);
579	    cJSON_Delete(root);
580	
581	    if (!json_body) {
582	        return -1;
583	    }
584	
585	    /* 根据服务类型构建 URL */
586	    switch (push_config.service) {
587	        case PUSH_SERVICE_BARK:
588	            snprintf(url, sizeof(url), "%s/%s/ZhiAi",
589	                    BARK_API_URL, push_config.push_key);
590	            break;
591	
592	        case PUSH_SERVICE_PUSHPLUS:
593	            /* PushPlus 使用 POST 请求，token 放在 JSON 里 */
594	            {
595	                cJSON *pp_root = cJSON_Parse(json_body);
596	                cJSON_AddStringToObject(pp_root, "token", push_config.push_key);
597	                free(json_body);
598	                json_body = cJSON_PrintUnformatted(pp_root);
599	                cJSON_Delete(pp_root);
600	                snprintf(url, sizeof(url), "%s", PUSHPLUS_API_URL);
601	            }
602	            break;
603	
604	        default:
605	            free(json_body);
606	            return -1;
607	    }
608	
609	    /* 发送 HTTP 请求 */
610	    int ret = http_post(url, json_body);
611	    free(json_body);
612	
613	    printf("push_send_notification: title=%s, ret=%d\n", title, ret);
614	    return ret;
615	}
