837	    if (lbl_time == NULL) {
838	        return;
839	    }
840	
841	    /* time() <= 0：说明时钟还没被设过（板上没有 RTC 备份电池，
842	     * 冷启动会读到 1900/2000 这类值）—— 用 "--:--" 明确表示"时间不可信"，
843	     * 比继续显示一个假的时间好。 */
844	    if (now <= 0) {
845	        lv_label_set_text(lbl_time, "--:--");
846	        return;
847	    }
848	
849	    /* UTC -> 本地时间（跨天由加法自然进位） */
850	    if (UI_TZ_OFFSET_SEC != 0) {
851	        now += UI_TZ_OFFSET_SEC;
852	    }
853	
854	    if (localtime_r(&now, &tm_buf) == NULL) {
855	        lv_label_set_text(lbl_time, "--:--");
856	        return;
857	    }
858	
859	    lv_label_set_text_fmt(lbl_time, "%02d:%02d",
860	                          tm_buf.tm_hour, tm_buf.tm_min);
861	}
