46	/**
47	 * 处理来自手机端或云端的 AI 命令
48	 * 成员二的 AI 模块可以通过此接口接收控制命令
49	 */
50	static void on_ai_command_received(const char *action, const char *param)
51	{
52	    printf("AI command: action=%s, param=%s\n", action, param);
53	
54	    if (strcmp(action, "start_voice") == 0) {
55	        /* 开始语音监听 */
56	        robot_ui_set_status(ROBOT_STATUS_LISTENING);
57	        robot_ui_set_face(ROBOT_FACE_THINKING);
58	        robot_ui_set_ai_reply("聆听中...\n请说话。");
59	
60	        /* 调用成员二的 AI 模块开始录音 */
61	        if (g_ai_initialized) {
62	            audio_record_start(&g_audio_ctx, NULL);
63	            sm_handle_event(&g_sm_ctx, SM_EVENT_WAKEUP);
64	        }
65	    }
66	    else if (strcmp(action, "stop_voice") == 0) {
67	        /* 停止语音监听 */
68	        robot_ui_set_status(ROBOT_STATUS_IDLE);
69	        robot_ui_set_face(ROBOT_FACE_HAPPY);
70	
71	        /* 调用成员二的 AI 模块停止录音 */
72	        if (g_ai_initialized) {
73	            audio_record_stop(&g_audio_ctx);
74	            sm_handle_event(&g_sm_ctx, SM_EVENT_VOICE_COMPLETE);
75	        }
76	    }
77	    else if (strcmp(action, "ai_reply") == 0) {
78	        /* 显示 AI 回复 */
79	        robot_ui_set_status(ROBOT_STATUS_SPEAKING);
80	        robot_ui_set_face(ROBOT_FACE_HAPPY);
81	        robot_ui_set_ai_reply(param);
82	
83	        /* 播放语音回复 */
84	        if (g_ai_initialized) {
85	            audio_play_start(&g_audio_ctx, NULL, 0, NULL, NULL);
86	        }
87	    }
88	    else if (strcmp(action, "start_remind") == 0) {
89	        /* 开始提醒 */
90	        robot_ui_set_status(ROBOT_STATUS_REMINDING);
91	        robot_ui_set_face(ROBOT_FACE_WORRIED);
92	        robot_ui_show_reminder("提醒", param);
93	    }
94	    else if (strcmp(action, "start_alarm") == 0) {
95	        /* 开始报警 */
96	        robot_ui_show_alarm(param);
97	
98	        /* 触发报警 */
99	        if (g_ai_initialized) {
100	            sm_handle_event(&g_sm_ctx, SM_EVENT_ALARM_DETECTED);
101	            report_alarm("sound_abnormal", param);
102	        }
103	    }
104	    else if (strcmp(action, "stop_alarm") == 0) {
105	        /* 停止报警 */
106	        robot_ui_close_alarm();
107	
108	        if (g_ai_initialized) {
109	            sm_handle_event(&g_sm_ctx, SM_EVENT_ALARM_CLEARED);
110	        }
111	    }
112	    else if (strcmp(action, "set_face") == 0) {
113	        /* 设置表情 */
114	        if (strcmp(param, "happy") == 0) {
115	            robot_ui_set_face(ROBOT_FACE_HAPPY);
116	        } else if (strcmp(param, "thinking") == 0) {
117	            robot_ui_set_face(ROBOT_FACE_THINKING);
118	        } else if (strcmp(param, "sleepy") == 0) {
119	            robot_ui_set_face(ROBOT_FACE_SLEEPY);
120	        } else if (strcmp(param, "surprised") == 0) {
121	            robot_ui_set_face(ROBOT_FACE_SURPRISED);
122	        } else if (strcmp(param, "worried") == 0) {
123	            robot_ui_set_face(ROBOT_FACE_WORRIED);
124	        }
125	    }
126	    else if (strcmp(action, "send_text") == 0) {
127	        /* 发送文本到 AI */
128	        if (g_ai_initialized) {
129	            robot_ui_set_status(ROBOT_STATUS_LISTENING);
130	            robot_ui_set_face(ROBOT_FACE_THINKING);
131	            llm_send_text(&g_llm_ctx, param, NULL, NULL, NULL);
132	        }
133	    }
134	}
