261	/**
262	 * 处理来自 MQTT 的消息
263	 * 解析命令并转发给 AI 命令处理函数
264	 */
265	static void on_mqtt_message_received(const char *topic, const char *payload)
266	{
267	    printf("MQTT received: topic=%s\n", topic);
268	
269	    /* 解析 JSON 命令 */
270	    cJSON *root = cJSON_Parse(payload);
271	    if (!root) {
272	        printf("JSON parse failed\n");
273	        return;
274	    }
275	
276	    cJSON *action = cJSON_GetObjectItem(root, "action");
277	    cJSON *param = cJSON_GetObjectItem(root, "param");
278	
279	    if (action && action->valuestring) {
280	        const char *param_str = (param && param->valuestring) ? param->valuestring : "";
281	        on_ai_command_received(action->valuestring, param_str);
282	    }
283	
284	    cJSON_Delete(root);
285	}
