288	int main(int argc, char *argv[])
289	{
290	    printf("ZhiAi Companion starting...\n");
291	
292	    /* ===== 初始化 LVGL 与显示设备（必须在 UI 创建之前） ===== */
293	    lv_init();
294	    lv_nuttx_dsc_t lv_info = {0};
295	    lv_nuttx_result_t lv_result = {0};
296	    lv_nuttx_dsc_init(&lv_info);
297	    lv_nuttx_init(&lv_info, &lv_result);
298	    if (lv_result.disp == NULL)
299	    {
300	        printf("LVGL display init failed!\n");
301	        return 1;
302	    }
303	
304	    /* ===== 初始化网络通信 ===== */
305	    network_comm_init();
306	
307	    /* ===== WiFi 连接 ===== */
308	    /* NOTE: 板子通过 USB RNDIS 上网，WiFi 代码未实际使用。
309	     * network_comm.c 中的 wifi_connect() 只是设置 wifi_config.connected = true，
310	     * 让 MQTT 能启动连接。不要删除此调用，否则 MQTT 不会连接。 */
311	    wifi_connect("RNDIS", "");
312	
313	    /* ===== 启动网络后台任务 =====
314	     * 负责 MQTT 连接 broker.emqx.io:1883、收消息、发心跳。
315	     * network_task() 一直存在但从来没被创建过，所以 MQTT 一次都没连上过。
316	     * 它自己会轮询 wifi_config.connected，所以放在 wifi_connect() 之后创建。
317	     */
318	    if (task_create("net_task", 100, 12288, (main_t)network_task, NULL) < 0) {
319	        printf("net_task create failed\n");
320	    }
321	
322	    /* ===== 初始化手机推送服务 ===== */
323	    /* PushPlus (Android 微信推送) */
324	    push_init(PUSH_SERVICE_PUSHPLUS, "1043ad84f9ba4dbb921756173d36277a");
325	    /* Bark (iPad iOS 推送) */
326	    push_init(PUSH_SERVICE_BARK, "726d1da9c292efcf947a85897c38310f6200a45c60ec8683813ae4d06fe67be9");
327	
328	    /* ===== 注册回调函数 ===== */
329	    network_set_mqtt_callback(on_mqtt_message_received);
330	    network_set_ai_command_callback(on_ai_command_received);
331	
332	    /* ===== 初始化 AI 模块 (成员二) ===== */
333	    printf("Initializing AI modules...\n");
334	
335	    /* 初始化状态机 */
336	    if (sm_init(&g_sm_ctx) == 0) {
337	        printf("State machine initialized\n");
338	    }
