340	    /* 初始化音频模块 */
341	    audio_config_t audio_config = {
342	        .sample_rate = AUDIO_RATE_16K,
343	        .channels = AUDIO_CH_MONO,
344	        .format = AUDIO_FORMAT_S16_LE
345	    };
346	    if (audio_init(&g_audio_ctx, &audio_config) == 0) {
347	        printf("Audio module initialized\n");
348	        /* 启用 VAD 检测 */
349	        audio_vad_enable(&g_audio_ctx, vad_callback, NULL);
350	    }
351	
352	    /* 初始化 LLM 模块 */
353	    if (llm_init(&g_llm_ctx, NULL) == 0) {
354	        printf("LLM module initialized\n");
355	    }
356	
357	    /* 初始化声音检测 */
358	    sound_detect_config_t detect_cfg = {
359	        .mode = DETECT_MODE_REALTIME,
360	        .threshold = SOUND_DETECT_THRESHOLD_DEFAULT,
361	        .sample_rate = SOUND_DETECT_SAMPLE_RATE,
362	        .frame_ms = SOUND_DETECT_FRAME_MS,
363	        .enable_vad = true,
364	        .enable_feedback = true,
365	        .callback = sound_alarm_callback,
366	        .user_data = NULL
367	    };
368	    if (sound_detect_init(&g_sound_ctx, &detect_cfg) == 0) {
369	        printf("Sound detect initialized\n");
370	    }
371	
372	    /* 初始化主动关怀 */
373	    care_config_t care_cfg = {
374	        .enable_greeting = true,
375	        .enable_health = true,
376	        .enable_life = true,
377	        .enable_exercise = true,
378	        .callback = care_remind_callback,
379	        .user_data = NULL
380	    };
381	    if (care_init(&g_care_ctx, &care_cfg) == 0) {
382	        printf("Care module initialized\n");
383	    }
384	
385	    g_ai_initialized = true;
386	    printf("AI modules initialization done\n");
387	
388	    /* ===== 初始化机器人 UI（先创建主屏并 lv_scr_load，成为活动屏） ===== */
389	    robot_ui_init();
390	
391	    /* ===== 初始化触摸交互 UI（须在活动屏 = 主屏之后, 菜单才可见） ===== */
392	    touch_ui_init();
393	
394	    /* ===== 添加默认提醒 ===== */
395	    touch_ui_add_reminder("吃药", "08:00");
396	    touch_ui_add_reminder("喝水", "10:00");
397	    touch_ui_add_reminder("散步", "16:00");
398	
399	    /* ===== 设置初始状态 ===== */
400	    robot_ui_set_status(ROBOT_STATUS_IDLE);
401	    robot_ui_set_face(ROBOT_FACE_HAPPY);
402	    robot_ui_set_ai_reply("你好！我是智爱陪伴\n有什么可以帮你的吗？");
403	
404	    /* ===== 显示主菜单 ===== */
405	    touch_ui_show_menu(MENU_TYPE_MAIN);
406	
407	    printf("ZhiAi Companion started!\n");
408	
409	    /* 主循环 */
410	    while (1) {
411	        static int  net_tick = 0;
412	        static bool net_ok   = false;
413	        static int  time_tick = 0;
414	
415	        lvgl_timer_handler();
416	
417	        /* 每 ~200ms 刷新一次状态栏上的网络状态。
418	         * LVGL 不是线程安全的，所以只在这个任务里改控件；network_task 那边
419	         * 只维护 mqtt_config.connected，由这里轮询。
420	         */
421	        if (++net_tick >= 40) {
422	            bool ok = mqtt_is_connected();
423	
424	            net_tick = 0;
425	            if (ok != net_ok) {
426	                net_ok = ok;
427	                robot_ui_set_net_status(ok ? "NET OK" : "NET --");
428	            }
429	        }
430	
431	        /* 每 ~1s 刷新状态栏时钟 */
432	        if (++time_tick >= 200) {
433	            time_tick = 0;
434	            robot_ui_update_time();
435	        }
436	
437	        /* 运行 AI 模块 */
438	        if (g_ai_initialized) {
439	            sm_run(&g_sm_ctx);
440	
441	            /* 运行关怀确认状态机 */
442	            ai_checkin_tick(lv_tick_get());
443	
444	            /* 轮询 checkin 状态并更新 UI */
445	            checkin_snapshot_t snap = ai_checkin_snapshot();
446	            static checkin_state_t last_checkin_state = CHECKIN_IDLE;
447	            if (snap.state != last_checkin_state) {
448	                last_checkin_state = snap.state;
449	                switch (snap.state) {
450	                    case CHECKIN_SENDING:
451	                        touch_ui_update_checkin_state(TOUCH_CHECKIN_SENDING);
452	                        break;
453	                    case CHECKIN_SENT:
454	                        touch_ui_update_checkin_state(TOUCH_CHECKIN_SENT);
455	                        /* 通知成功后 2 秒自动关闭面板 */
456	                        /* TODO: 用 lv_timer 延迟关闭 */
457	                        break;
458	                    case CHECKIN_FAILED:
459	                        touch_ui_update_checkin_state(TOUCH_CHECKIN_FAILED);
460	                        break;
461	                    case CHECKIN_IDLE:
462	                        /* 确认流程结束，隐藏面板 */
463	                        touch_ui_hide_checkin();
464	                        break;
465	                    default:
466	                        break;
467	                }
468	            }
469	        }
470	
471	        usleep(5000); // 5ms 刷新周期
472	    }
473	
474	    return 0;
475	}
