68	/* ==================== 编码 MQTT 剩余长度 ==================== */
69	static int mqtt_encode_remaining_length(uint8_t *buf, int length)
70	{
71	    int pos = 0;
72	    do {
73	        uint8_t byte = length % 128;
74	        length /= 128;
75	        if (length > 0) {
76	            byte |= 0x80;
77	        }
78	        buf[pos++] = byte;
79	    } while (length > 0);
80	    return pos;
81	}
