110	/* ==================== WiFi 连接 ==================== */
111	int wifi_connect(const char *ssid, const char *password)
112	{
113	    printf("WiFi connecting: %s\n", ssid);
114	
115	    /* 保存配置 */
116	    strncpy(wifi_config.ssid, ssid, sizeof(wifi_config.ssid) - 1);
117	    strncpy(wifi_config.password, password, sizeof(wifi_config.password) - 1);
118	
119	    /* NuttX WiFi 连接实现 */
120	    #ifdef CONFIG_NETINET_WIRELESS
121	    #include <nuttx/wireless/wireless.h>
122	
123	    /* 打开网络设备 */
124	    int fd = open("/dev/wlan0", O_RDWR);
125	    if (fd < 0) {
126	        printf("WiFi: open /dev/wlan0 failed: %d\n", errno);
127	        return -1;
128	    }
129	
130	    /* 设置 WiFi 模式为 Station */
131	    struct wireless_config_s wconfig;
132	    memset(&wconfig, 0, sizeof(wconfig));
133	    strncpy(wconfig.essid, ssid, sizeof(wconfig.essid) - 1);
134	    wconfig.has_essid = true;
135	    wconfig.mode = IW_MODE_INFRA;
136	
137	    int ret = ioctl(fd, SIOCSIWLCFG, &wconfig);
138	    if (ret < 0) {
139	        printf("WiFi: set mode failed: %d\n", errno);
140	        close(fd);
141	        return -1;
142	    }
143	
144	    /* 设置密码（WPA2） */
145	    struct iwreq wr;
146	    memset(&wr, 0, sizeof(wr));
147	    strncpy(wr.ifr_name, "wlan0", IFNAMSIZ);
148	
149	    struct iw_encode_ext *ext = malloc(sizeof(struct iw_encode_ext) + strlen(password));
150	    if (ext) {
151	        memset(ext, 0, sizeof(*ext));
152	        ext->alg = SIOCSIWENCODEEXT;
153	        ext->key_len = strlen(password);
154	        ext->ext_flags |= IW_ENCODE_EXT_SET_CRYPT_KEY;
155	        memcpy(ext->key, password, strlen(password));
156	
157	        wr.u.data.pointer = ext;
158	        wr.u.data.length = sizeof(*ext) + strlen(password);
159	
160	        ret = ioctl(fd, SIOCSIWENCODEEXT, &wr);
161	        free(ext);
162	
163	        if (ret < 0) {
164	            printf("WiFi: set password failed: %d\n", errno);
165	            close(fd);
166	            return -1;
167	        }
168	    }
169	
170	    /* 连接网络 */
171	    memset(&wconfig, 0, sizeof(wconfig));
172	    strncpy(wconfig.essid, ssid, sizeof(wconfig.essid) - 1);
173	    wconfig.has_essid = true;
174	
175	    ret = ioctl(fd, SIOCSIWESSID, &wconfig);
176	    if (ret < 0) {
177	        printf("WiFi: connect failed: %d\n", errno);
178	        close(fd);
179	        return -1;
180	    }
181	
182	    close(fd);
183	    #endif
184	
185	    /* 模拟连接成功（如果上面的驱动不可用） */
186	    wifi_config.connected = true;
187	    wifi_config.rssi = -50;
188	
189	    printf("WiFi connected: %s\n", ssid);
190	
191	    /* 触发回调 */
192	    if (wifi_callback) {
193	        wifi_callback(true);
194	    }
195	
196	    return 0;
197	}
