201	{
202	    /* NuttX WiFi 断开实现 */
203	    #ifdef CONFIG_NETINET_WIRELESS
204	    int fd = open("/dev/wlan0", O_RDWR);
205	    if (fd >= 0) {
206	        /* 断开连接 */
207	        struct wireless_config_s wconfig;
208	        memset(&wconfig, 0, sizeof(wconfig));
209	        wconfig.has_essid = true;
210	
211	        ioctl(fd, SIOCSIWESSID, &wconfig);
212	        close(fd);
213	    }
214	    #endif
215	
216	    wifi_config.connected = false;
217	    printf("WiFi disconnected\n");
218	
219	    if (wifi_callback) {
220	        wifi_callback(false);
221	    }
222	
223	    return 0;
224	}
