533	/* 发送推送通知 */
534	int push_send_notification(const char *title, const char *content, const char *group)
535	{
536	    if (!push_config.enabled || push_config.push_key[0] == '\0') {
537	        printf("push_send_notification: push not enabled\n");
538	        return -1;
539	    }
540	
541	    char url[256] = {0};
542	    char body[HTTP_BUFFER_SIZE] = {0};
543	
544	    /* 构建 JSON 请求体 */
545	    cJSON *root = cJSON_CreateObject();
546	    cJSON_AddStringToObject(root, "title", title);
547	    cJSON_AddStringToObject(root, "body", content);
548	    if (group) {
549	        cJSON_AddStringToObject(root, "group", group);
550	    }
551	    cJSON_AddStringToObject(root, "device", "ZhiAi-Companion");
552	
553	    char *json_body = cJSON_PrintUnformatted(root);
554	    cJSON_Delete(root);
555	
556	    if (!json_body) {
557	        return -1;
558	    }
559	
560	    /* 根据服务类型构建 URL */
561	    switch (push_config.service) {
562	        case PUSH_SERVICE_BARK:
563	            snprintf(url, sizeof(url), "%s/%s/ZhiAi",
564	                    BARK_API_URL, push_config.push_key);
565	            break;
566	
567	        case PUSH_SERVICE_PUSHPLUS:
568	            /* PushPlus 使用 POST 请求，token 放在 JSON 里 */
569	            {
570	                cJSON *pp_root = cJSON_Parse(json_body);
571	                cJSON_AddStringToObject(pp_root, "token", push_config.push_key);
572	                free(json_body);
573	                json_body = cJSON_PrintUnformatted(pp_root);
574	                cJSON_Delete(pp_root);
575	                snprintf(url, sizeof(url), "%s", PUSHPLUS_API_URL);
576	            }
577	            break;
578	
579	        default:
580	            free(json_body);
581	            return -1;
582	    }
583	
584	    /* 发送 HTTPS 请求 */
585	    int ret = https_post(url, json_body);
586	    free(json_body);
587	
588	    printf("push_send_notification: title=%s, ret=%d\n", title, ret);
589	    return ret;
590	}
