804	
805	/* 创建 TCP Socket */
806	static int create_tcp_socket(const char *host, uint16_t port)
807	{
808	    int sockfd;
809	    struct sockaddr_in server_addr;
810	
811	    /* 创建 socket */
812	    sockfd = socket(AF_INET, SOCK_STREAM, 0);
813	    if (sockfd < 0) {
814	        perror("socket");
815	        return -1;
816	    }
817	
818	    /* 设置服务器地址 */
819	    memset(&server_addr, 0, sizeof(server_addr));
820	    server_addr.sin_family = AF_INET;
821	    server_addr.sin_port = htons(port);
822	
823	    /* 解析主机名或 IP */
824	    struct hostent *he = gethostbyname(host);
825	    if (he) {
826	        memcpy(&server_addr.sin_addr, he->h_addr_list[0], he->h_length);
827	        printf("MQTT DNS: %s -> %s\n", host, inet_ntoa(server_addr.sin_addr));
828	    } else {
829	        server_addr.sin_addr.s_addr = inet_addr(host);
830	        printf("MQTT DNS: %s 解析失败, 当 IP 用\n", host);
831	    }
832	
833	    /* 连接服务器。
834	     *
835	     * 必须用「非阻塞 connect + select 超时」，不能直接用阻塞式 connect：
836	     * 对方如果不回 SYN（被限流、网络抖动、IP 过期），内核要等 SYN 重传耗尽
837	     * 才返回，在 NuttX 的配置下要 1~3 分钟。而 network_task 是单线程轮询，
838	     * 这一个 connect 就会把整个任务卡住——心跳不发、重连不做、串口一行日志
839	     * 都没有，看起来像"死机"。5 秒返回不了就当这次失败，下一轮重试。
840	     */
841	    if (fcntl(sockfd, F_SETFL, O_NONBLOCK) < 0) {
842	        perror("fcntl");
843	        close(sockfd);
844	        return -1;
845	    }
846	
847	    int cret = connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
848	    if (cret < 0 && errno != EINPROGRESS) {
849	        perror("connect");
850	        close(sockfd);
851	        return -1;
852	    }
853	
854	    if (cret < 0) {
855	        fd_set wset;
856	        struct timeval ctimeo;
857	        int cerr = 0;
858	        socklen_t elen = sizeof(cerr);
859	
860	        FD_ZERO(&wset);
861	        FD_SET(sockfd, &wset);
862	        ctimeo.tv_sec  = 5;
863	        ctimeo.tv_usec = 0;
864	
865	        if (select(sockfd + 1, NULL, &wset, NULL, &ctimeo) <= 0 ||
866	            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &cerr, &elen) < 0 ||
867	            cerr != 0) {
868	            printf("connect timeout/error: %s:%u\n", host, (unsigned)port);
869	            close(sockfd);
870	            return -1;
871	        }
872	    }
873	
874	    /* 保持非阻塞。
875	     *
876	     * network_task 是单线程轮询，任何一次阻塞都可能把整个循环卡死：
877	     * 心跳不发、重连不做、串口一行日志都没有，看起来像"死机"（实测过）。
878	     * 原来这里靠 SO_RCVTIMEO 让 recv 5 秒超时返回，但实测不可靠 ——
879	     * 循环会永久停在 recv 里。
880	     *
881	     * 非阻塞之后：没数据时 recv 立刻返回 -1，mqtt_parse_packet() 直接返回，
882	     * 循环继续跑，心跳照发、重连照做。
883	     */
884	    if (fcntl(sockfd, F_SETFL, O_NONBLOCK) < 0) {
885	        perror("fcntl");
886	        close(sockfd);
887	        return -1;
888	    }
889	
890	    return sockfd;
891	}
