985	/* 发送 MQTT SUBSCRIBE 包 */
986	static int mqtt_send_subscribe(const char *topic, int qos)
987	{
988	    uint8_t packet[256];
989	    int pos = 0;
990	
991	    /* 固定头: SUBSCRIBE = 0x82 */
992	    packet[pos++] = 0x82;
993	
994	    /* 剩余长度 = 2(包ID) + 2(topic长度) + topic_len + 1(QoS) */
995	    int topic_len = strlen(topic);
996	    int remaining = 2 + 2 + topic_len + 1;
997	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
998	
999	    /* 包 ID */
1000	    static uint16_t subscribe_id = 0;
1001	    subscribe_id++;
1002	    packet[pos++] = (subscribe_id >> 8) & 0xFF;
1003	    packet[pos++] = subscribe_id & 0xFF;
1004	
1005	    /* 主题过滤器 */
1006	    packet[pos++] = (topic_len >> 8) & 0xFF;
1007	    packet[pos++] = topic_len & 0xFF;
1008	    memcpy(&packet[pos], topic, topic_len);
1009	    pos += topic_len;
1010	
1011	    /* QoS */
1012	    packet[pos++] = qos;
1013	
1014	    return send(mqtt_socket, packet, pos, 0);
1015	}
