1072	/* 解析 MQTT 数据包 */
1073	static int mqtt_parse_packet(void)
1074	{
1075	    uint8_t buffer[1024];
1076	    int len = recv(mqtt_socket, buffer, sizeof(buffer), 0);
1077	    if (len <= 0) {
1078	        return -1;
1079	    }
1080	
1081	    uint8_t type = (buffer[0] >> 4) & 0x0F;
1082	
1083	    switch (type) {
1084	        case 0x0D:  // PINGRESP
1085	            printf("Received PINGRESP\n");
1086	            break;
1087	
1088	        case 0x03:  // PUBLISH
1089	            /* 解析主题和载荷 */
1090	            {
1091	                int pos = 1;
1092	
1093	                /* 跳过剩余长度编码 */
1094	                int remaining = 0;
1095	                int multiplier = 1;
1096	                do {
1097	                    remaining += (buffer[pos] & 0x7F) * multiplier;
1098	                    multiplier *= 128;
1099	                    pos++;
1100	                } while (buffer[pos - 1] & 0x80);
1101	
1102	                /* 解析主题 */
1103	                int topic_len = (buffer[pos] << 8) | buffer[pos + 1];
1104	                pos += 2;
1105	
1106	                char topic[128];
1107	                int copy_len = topic_len < (int)(sizeof(topic) - 1) ? topic_len : (int)(sizeof(topic) - 1);
1108	                memcpy(topic, &buffer[pos], copy_len);
1109	                topic[copy_len] = '\0';
1110	                pos += topic_len;
1111	
1112	                /* 解析载荷 */
1113	                char payload[1024];
1114	                int payload_len = len - pos;
1115	                if (payload_len > (int)(sizeof(payload) - 1)) {
1116	                    payload_len = (int)(sizeof(payload) - 1);
1117	                }
1118	                memcpy(payload, &buffer[pos], payload_len);
1119	                payload[payload_len] = '\0';
1120	
1121	                printf("Received: topic=%s, payload=%s\n", topic, payload);
1122	
1123	                /* 调用回调 */
1124	                if (mqtt_callback) {
1125	                    mqtt_callback(topic, payload);
1126	                }
1127	            }
1128	            break;
1129	
1130	        default:
1131	            printf("Unknown packet type: %d\n", type);
1132	            break;
1133	    }
1134	
1135	    return 0;
1136	}
