1172	/* ==================== 网络任务（后台运行） ==================== */
1173	void network_task(void *arg)
1174	{
1175	    printf("network_task started\n");
1176	
1177	    /* MQTT 重连节流 + broker 降级。每次尝试都要先做 DNS 解析再 connect：
1178	     * - 每 100ms 重来一次会把 CPU 和网络打满；
1179	     * - 一直 5 秒一次地锤公共 broker 会被限流（broker.emqx.io 就把我们
1180	     *   限了：连着 20 多分钟后它开始直接关连接、不给 CONNACK）。
1181	     * 所以前几次快一点（开机后尽快连上），失败多了就放慢到 30 秒；
1182	     * 连了 5 次还不行就换下一台 broker。
1183	     */
1184	    int mqtt_retry_tick = 0;
1185	    int mqtt_fails = 0;
1186	    int broker_idx = 0;
1187	    int broker_switches = 0;
1188	
1189	    while (1) {
1190	        /* 检查 WiFi 状态 */
1191	        if (!wifi_config.connected) {
1192	            /* 尝试重连 */
1193	            // TODO: 实现重连逻辑
1194	        }
1195	
1196	        /* 检查 MQTT 状态 */
1197	        if (wifi_config.connected && !mqtt_config.connected) {
1198	            if (--mqtt_retry_tick <= 0) {
1199	                /* 只有第一轮（还没换过 broker）才用 5 秒的快节奏，好在开机后
1200	                 * 尽快连上；一旦开始换 broker 说明网络/公共实例有问题，一律 30 秒，
1201	                 * 否则会变成"每台试 5 次、15 次一轮"地一直锤公共服务器。
1202	                 */
1203	                mqtt_retry_tick =
1204	                    (broker_switches == 0 && mqtt_fails < 5) ? 50 : 300;
1205	
1206	                /* 尝试连接 MQTT */
1207	                if (mqtt_connect(mqtt_config.broker, mqtt_config.port,
1208	                                 mqtt_config.client_id, mqtt_config.username,
1209	                                 mqtt_config.password) < 0) {
1210	                    mqtt_fails++;
1211	
1212	                    if (mqtt_fails >= 5 && MQTT_NBROKERS > 1) {
1213	                        /* 这台连不上（公共实例限流很常见），换下一台 */
1214	                        broker_idx = (broker_idx + 1) % MQTT_NBROKERS;
1215	                        broker_switches++;
1216	                        strncpy(mqtt_config.broker, g_mqtt_broker_list[broker_idx],
1217	                                sizeof(mqtt_config.broker) - 1);
1218	                        mqtt_config.broker[sizeof(mqtt_config.broker) - 1] = '\0';
1219	                        printf("MQTT broker 切换到 %s\n", mqtt_config.broker);
1220	                        mqtt_fails = 0;
1221	                    }
1222	                } else {
1223	                    mqtt_fails = 0;
1224	                }
1225	            }
1226	        }
1227	
1228	        /* 接收 MQTT 消息 */
1229	        if (mqtt_config.connected) {
1230	            mqtt_parse_packet();
1231	
1232	            /* 发送心跳 */
1233	            uint32_t now = (uint32_t)time(NULL) * 1000;
1234	            if (now - last_heartbeat_time >= HEARTBEAT_INTERVAL) {
1235	                report_heartbeat();
1236	                last_heartbeat_time = now;
1237	            }
1238	        }
1239	
1240	        usleep(100000);  // 100ms
1241	    }
1242	}
