157	static void ui_clock_refresh(void)
158	{
159	    time_t now = time(NULL);
160	    struct tm tm_buf;
161	
162	    if (lbl_time == NULL) {
163	        return;
164	    }
165	
166	    /* time() <= 0：说明时钟还没被设过（板上没有 RTC 备份电池，
167	     * 冷启动会读到 1900/2000 这类值）—— 用 "--:--" 明确表示"时间不可信"，
168	     * 比继续显示一个假的时间好。 */
169	    if (now <= 0) {
170	        lv_label_set_text(lbl_time, "--:--");
171	        return;
172	    }
173	
174	    /* UTC -> 本地时间（跨天由加法自然进位） */
175	    if (UI_TZ_OFFSET_SEC != 0) {
176	        now += UI_TZ_OFFSET_SEC;
177	    }
178	
179	    if (localtime_r(&now, &tm_buf) == NULL) {
180	        lv_label_set_text(lbl_time, "--:--");
