153	/* ==================== 初始化触摸交互 UI ==================== */
154	void touch_ui_init(void)
155	{
156	    /* 初始化样式 */
157	    init_elder_styles();
158	
159	    /* 初始化提醒列表 */
160	    memset(reminders, 0, sizeof(reminders));
161	    reminder_count = 0;
162	
163	    /* 面板句柄复位: NuttX builtin 应用重新运行时 .bss 不清零,
164	     * 若残留上一次运行的面板指针, 之后 lv_obj_del() 会去删除已
165	     * 失效的 LVGL 对象而导致 hardfault */
166	    menu_panel = NULL;
167	    setting_panel = NULL;
168	    reminder_panel = NULL;
169	
170	    /* 获取当前活动屏幕 */
171	    current_screen = lv_scr_act();
172	    lv_obj_add_style(current_screen, &style_elder, 0);
173	
174	    printf("touch_ui init done\n");
175	}
