177	/* ==================== 显示菜单 ==================== */
178	void touch_ui_show_menu(menu_type_t type)
179	{
180	    /* 清除所有旧面板. 注意 setting_panel 是活动屏的兄弟节点,
181	     * 不挂在 menu_panel 下, 只删 menu_panel 会遗留旧设置面板,
182	     * 导致新旧面板重叠且整棵对象树泄漏 */
183	    if (menu_panel) {
184	        lv_obj_del(menu_panel);
185	        menu_panel = NULL;
186	    }
187	    if (setting_panel) {
188	        lv_obj_del(setting_panel);
189	        setting_panel = NULL;
190	    }
191	    if (reminder_panel) {
192	        lv_obj_del(reminder_panel);
193	        reminder_panel = NULL;
194	    }
195	
196	    /* 创建菜单面板 */
197	    create_menu_panel(type);
198	}
199	
200	/* ==================== 隐藏菜单 ==================== */
201	void touch_ui_hide_menu(void)
202	{
203	    if (menu_panel) {
204	        lv_obj_del(menu_panel);
205	        menu_panel = NULL;
206	    }
207	}
