209	/* ==================== 返回上一级 ==================== */
210	void touch_ui_go_back(void)
211	{
212	    /* 隐藏所有面板 */
213	    touch_ui_hide_menu();
214	
215	    if (setting_panel) {
216	        lv_obj_del(setting_panel);
217	        setting_panel = NULL;
218	    }
219	
220	    if (reminder_panel) {
221	        lv_obj_del(reminder_panel);
222	        reminder_panel = NULL;
223	    }
224	
225	    /* 播放返回音效 */
226	    touch_ui_play_sound("back");
227	}
