229	/* ==================== 创建菜单面板 ==================== */
230	static void create_menu_panel(menu_type_t type)
231	{
232	    /* 菜单容器 */
233	    menu_panel = lv_obj_create(current_screen);
234	    lv_obj_set_size(menu_panel, LV_PCT(95), LV_PCT(85));
235	    lv_obj_align(menu_panel, LV_ALIGN_CENTER, 0, 0);
236	    lv_obj_add_style(menu_panel, &style_elder, 0);
237	    lv_obj_set_flex_flow(menu_panel, LV_FLEX_FLOW_COLUMN);
238	    lv_obj_set_flex_align(menu_panel, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
239	    lv_obj_set_style_pad_all(menu_panel, 20, 0);
240	    lv_obj_set_style_pad_row(menu_panel, 15, 0);
241	
242	    /* 标题 */
243	    lv_obj_t *title = lv_label_create(menu_panel);
244	    switch (type) {
245	        case MENU_TYPE_MAIN:
246	            lv_label_set_text(title, "[主] 主菜单");
247	            break;
248	        case MENU_TYPE_REMIND:
249	            lv_label_set_text(title, "[提] 提醒");
250	            break;
251	        case MENU_TYPE_SETTING:
252	            lv_label_set_text(title, "[设] 设置");
253	            break;
254	        case MENU_TYPE_ABOUT:
255	            lv_label_set_text(title, "[?] 关于");
256	            break;
257	        default:
258	            lv_label_set_text(title, "菜单");
259	            break;
260	    }
261	    lv_obj_set_style_text_font(title, &lv_font_ui_24, 0);
262	    lv_obj_set_style_text_color(title, lv_color_hex(0xFFEB3B), 0);
263	    lv_obj_set_style_pad_bottom(title, 20, 0);
264	
265	    /* 根据菜单类型创建内容 */
266	    switch (type) {
267	        case MENU_TYPE_MAIN:
268	            create_menu_item(menu_panel, "[语] 语音聊天", "与机器人对话", 0);
269	            create_menu_item(menu_panel, "[提] 查看提醒", "查看今日提醒", 1);
270	            create_menu_item(menu_panel, "[设] 设置", "音量、亮度等", 2);
271	            create_menu_item(menu_panel, "[急] 紧急呼叫", "联系家人", 3);
272	            create_menu_item(menu_panel, "[?] 关于", "版本信息", 4);
273	            break;
274	
275	        case MENU_TYPE_REMIND:
276	            create_reminder_list_items(menu_panel);
277	            break;
278	
279	        case MENU_TYPE_SETTING:
280	            create_setting_panel();
281	            break;
282	
283	        case MENU_TYPE_ABOUT:
284	            create_about_info(menu_panel);
285	            break;
286	
287	        default:
288	            break;
289	    }
290	
291	    /* 返回按钮 */
292	    create_back_button(menu_panel);
293	}
