532	        lv_obj_t *btn_label = lv_label_create(btn);
533	        lv_label_set_text(btn_label, interval_texts[i]);
534	        lv_obj_set_style_text_font(btn_label, &lv_font_ui_16, 0);
535	        lv_obj_center(btn_label);
536	    }
537	}
