612	/* 滑块值改变事件 */
613	static void setting_slider_event_handler(lv_event_t *e)
614	{
615	    lv_obj_t *slider = lv_event_get_target(e);
616	    int index = (int)(intptr_t)lv_event_get_user_data(e);
617	    int value = lv_slider_get_value(slider);
618	    int ret;
619	
620	    switch (index) {
621	        case 0: // 音量
622	            user_settings.volume = value;
623	            break;
624	        case 1: // 亮度
625	            user_settings.brightness = value;
626	
627	            /* 回调里只设值，不做重活：backlight_set() 内部是懒打开的 fd +
628	             * 两个 ioctl。失败只打一行。未打 vendor 补丁的树上 1..99 会回
629	             * -ENOSYS（见 sf32lb52_backlight.h 文件头）。 */
630	            ret = backlight_set(value);
631	            if (ret != OK)
632	                printf("touch_ui: backlight_set(%d) failed: %d\n", value, ret);
633	            break;
634	        default:
635	            break;
636	    }
637	}
