946	/* 更新关怀确认状态（lv_async_call 投递到 LVGL 线程） */
947	static void update_checkin_state_async(void *state_ptr)
948	{
949	    touch_checkin_state_t state = (touch_checkin_state_t)(intptr_t)state_ptr;
950	    if (!checkin_status_lbl) return;
951	
952	    switch (state) {
953	        case TOUCH_CHECKIN_WAITING:
954	            lv_label_set_text(checkin_status_lbl, "等待确认");
955	            lv_obj_set_style_text_color(checkin_status_lbl, lv_color_hex(0x4CAF50), 0);
956	            if (checkin_btn_fine) lv_obj_clear_state(checkin_btn_fine, LV_STATE_DISABLED);
957	            if (checkin_btn_help) lv_obj_clear_state(checkin_btn_help, LV_STATE_DISABLED);
958	            checkin_confirmed = false;
959	            break;
960	        case TOUCH_CHECKIN_SENDING:
961	            lv_label_set_text(checkin_status_lbl, "正在通知...");
962	            lv_obj_set_style_text_color(checkin_status_lbl, lv_color_hex(0xFFC107), 0);
