151	 * 注：更"正规"的做法是开 CONFIG_LIBC_LOCALTIME 并设 TZ，但那会换掉
152	 * mktime/localtime 的实现，而 `RTC_SET_RELATIVE`（sf32lb_rtc.c 的 add_timeout）
153	 * 正好依赖现在这套简化日历换算，**不建议现在动**；显示层加偏移最省事也最可控。 */
154	#define UI_TZ_OFFSET_SEC  (8 * 3600)
155	
156	/* 从系统时钟（硬件 RTC）读一次，刷新状态栏上的时间标签（本地时间）。 */
157	static void ui_clock_refresh(void)
158	{
159	    time_t now = time(NULL);
160	    struct tm tm_buf;
161	
162	    if (lbl_time == NULL) {
163	        return;
164	    }
165	
166	    /* time() <= 0：说明时钟还没被设过（板上没有 RTC 备份电池，
167	     * 冷启动会读到 1900/2000 这类值）—— 用 "--:--" 明确表示"时间不可信"，
168	     * 比继续显示一个假的时间好。 */
169	    if (now <= 0) {
170	        lv_label_set_text(lbl_time, "--:--");
171	        return;
172	    }
173	
174	    /* UTC -> 本地时间（跨天由加法自然进位） */
175	    if (UI_TZ_OFFSET_SEC != 0) {
176	        now += UI_TZ_OFFSET_SEC;
177	    }
178	
179	    if (localtime_r(&now, &tm_buf) == NULL) {
180	        lv_label_set_text(lbl_time, "--:--");
181	        return;
182	    }
183	
184	    lv_label_set_text_fmt(lbl_time, "%02d:%02d",
185	                          tm_buf.tm_hour, tm_buf.tm_min);
186	}
187	
188	static void ui_clock_timer_cb(lv_timer_t *t)
189	{
190	    (void)t;
191	    ui_clock_refresh();
192	}
