194	/* ==================== 创建状态栏 ==================== */
195	static void create_status_bar(lv_obj_t *parent)
196	{
197	    /* 状态栏容器 */
198	    lv_obj_t *bar = lv_obj_create(parent);
199	    lv_obj_set_size(bar, LV_PCT(100), 40);
200	    lv_obj_align(bar, LV_ALIGN_TOP_MID, 0, 0);
201	    lv_obj_set_style_bg_color(bar, lv_color_hex(0x2D2D44), 0);
202	    lv_obj_set_style_border_width(bar, 0, 0);
203	    lv_obj_set_style_radius(bar, 0, 0);
204	    lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
205	    lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
206	
207	    /* 状态文本 */
208	    lbl_status = lv_label_create(bar);
209	    lv_label_set_text(lbl_status, "[在线]");
210	    lv_obj_set_style_text_color(lbl_status, lv_color_hex(0x4CAF50), 0);
211	    lv_obj_set_style_text_font(lbl_status, &lv_font_ui_24, 0);
212	
213	    /* 时间标签：从系统时钟（硬件 RTC）读真实时间，并定时刷新。
214	     *
215	     * 原来这里是写死的 lv_label_set_text(lbl_time, "12:00")，所以主页面顶上
216	     * **永远显示 12:00**，跟板子时间毫无关系。
217	     *
218	     * 数据源用 time(NULL)：NuttX 启动时用 RTC 初始化系统时钟，
219	     * 而 RTC_SET_TIME（含 NSH 的 `date -s`）会同步系统时钟，所以它就是板子的时间。
220	     * 板上没有 RTC 备份电池，掉电后时间会丢，要在 NSH 里重新对时：
221	     *     date -s "Sep 13 12:00:00 2026"
222	     *
223	     * 注意：本构建没开 CONFIG_LIBC_LOCALTIME，`localtime` 实际就是 `gmtime`，
224	     * 所以**显示的是 UTC**，比北京时间少 8 小时。要显示本地时间得自己加偏移
225	     * （这里刻意不加，保持"屏幕上显示的就是 RTC 里的值"，免得排查时对不上）。 */
226	    lbl_time = lv_label_create(bar);
227	    lv_obj_set_style_text_color(lbl_time, lv_color_hex(0xFFFFFF), 0);
228	    lv_obj_set_style_text_font(lbl_time, &lv_font_ui_24, 0);
229	    ui_clock_refresh();                                      /* 先立刻显示一次 */
230	    clock_timer = lv_timer_create(ui_clock_timer_cb, 10000, NULL);  /* 每 10 秒刷一次 */
231	
232	    /* 电量/网络图标（简化为文字） */
233	    lv_obj_t *lbl_signal = lv_label_create(bar);
234	    lv_label_set_text(lbl_signal, "WiFi 100%");
235	    lv_obj_set_style_text_color(lbl_signal, lv_color_hex(0xFFFFFF), 0);
236	    lv_obj_set_style_text_font(lbl_signal, &lv_font_ui_24, 0);
237	
238	    /* 网络状态:由 main 的主循环轮询 network_is_connected() 后刷新，
239	     * 不在 network_task 里直接改，避免跨任务操作 LVGL。
240	     * 这里显示的是 network_task 给的 ASCII 状态串（NET OK / NET --）。
241	     */
242	    lbl_net = lv_label_create(bar);
243	    lv_label_set_text(lbl_net, "NET --");
244	    lv_obj_set_style_text_color(lbl_net, lv_color_hex(0xFFC107), 0);
245	    lv_obj_set_style_text_font(lbl_net, &lv_font_ui_24, 0);
246	}
