388	                break;
389	            case UI_VIEW_SETTING:
390	                touch_ui_show_menu(MENU_TYPE_SETTING);
391	                break;
392	            case UI_VIEW_ALARM:
393	                robot_ui_show_alarm("Abnormal detected!\nPlease confirm if help is needed.");
394	                break;
395	            case UI_VIEW_MAIN:
396	                /* 报警界面 Back 按钮:关闭报警，返回主界面 */
397	                robot_ui_close_alarm();
398	                break;
399	            default:
400	                break;
401	        }
402	    }
403	}
