571	void robot_ui_show_alarm(const char *content)
572	{
573	    int ret;
574	
575	    /* 设备级动作：让喇叭真的响起来（板级报警模块，非阻塞返回）。
576	     *
577	     * 放在这个函数里、而不是各个调用点，是因为界面上的"报警"按钮走的是
578	     *   btn_event_handler() -> robot_ui_show_alarm()
579	     * 根本不经过 main.c；而这里是所有报警入口（按钮 / MQTT 的 start_alarm /
580	     * 声音检测回调）唯一的汇合点，改一处就全接上了。也不会重复触发：
581	     * alarm_trigger() 对同级或更低的重复触发只更新 reason/text，不重来。
582	     *
583	     * 这里**不受 main.c 里 g_ai_initialized / #if 0 的影响**：robot_ui.c
584	     * 完全不引用那个标志，所以 AI 初始化整块停用也照样出声。
585	     */
586	    ret = alarm_trigger(ALARM_LEVEL_EMERGENCY, "ui",
587	                        "报警已触发，请尽快确认");
588	    if (ret != OK) {
589	        printf("robot_ui: alarm_trigger failed: %d\n", ret);
590	    }
591	
592	    /* 上报：MQTT 发到 zhi_ai/<client_id>/alarm（+ 手机推送）。
593	     * 以前这里没接，所以按了报警按钮只响、不上报；补上这一句
594	     * 才算"响 + 屏幕 + 上报 + 推送"四个动作齐全。
595	     * 注意 report_alarm() 不阻塞（MQTT 没连上时它内部会很快失败返回）。 */
596	    {
597	        int rret = report_alarm("ui", "用户按下报警按钮");
598	        if (rret < 0) {
599	            printf("robot_ui: report_alarm failed: %d（MQTT 没连上？）\n", rret);
600	        }
601	    }
602	
603	    /* 切换到报警屏幕 */
604	    lv_scr_load(scr_alarm);
605	
606	    /* 设置报警表情 */
607	    robot_ui_set_face(ROBOT_FACE_ALARM);
608	    robot_ui_set_status(ROBOT_STATUS_ALARM);
609	
610	    /* 启动报警闪烁动画 */
611	    lv_anim_start(&anim_blink);
612	}
613	
614	/* ==================== 关闭报警 ==================== */
615	void robot_ui_close_alarm(void)
616	{
617	    int ret;
618	
619	    /* 设备级动作：停掉报警声（没有在报警时是安全空操作） */
620	    ret = alarm_clear();
621	    if (ret != OK) {
622	        printf("robot_ui: alarm_clear failed: %d\n", ret);
623	    }
624	
625	    /* 停止闪烁动画 */
626	    /* v9 语义: lv_anim_delete(var, exec_cb) 第一个参数是动画绑定的对象
627	     * (anim_blink.var == scr_alarm), 不是 lv_anim_t 结构体地址 */
628	    lv_anim_delete(anim_blink.var, anim_blink_update);
629	
630	    /* 返回主界面 */
631	    lv_scr_load(scr_main);
632	
633	    /* 恢复正常状态 */
634	    robot_ui_set_face(ROBOT_FACE_HAPPY);
635	    robot_ui_set_status(ROBOT_STATUS_IDLE);
636	}
