638	/* ==================== 切换界面 ==================== */
639	void robot_ui_switch_view(ui_view_t view)
640	{
641	    switch (view) {
642	        case UI_VIEW_MAIN:
643	            lv_scr_load(scr_main);
644	            break;
645	        case UI_VIEW_ALARM:
646	            lv_scr_load(scr_alarm);
647	            break;
648	        default:
649	            break;
650	    }
651	}
