68	void EmojiPlayer::StartPlayer(const std::string& asset_name, bool repeat, int fps) {
69	    if (player_handle_) {
70	        uint32_t start, end;
71	        void* src_data = nullptr;
72	        size_t src_len = 0;
73	
74	        auto& assets = Assets::GetInstance();
75	        auto filename_iter = emoji_asset_name_map.find(asset_name);
76	        if (filename_iter == emoji_asset_name_map.end()) {
77	            ESP_LOGE(TAG, "Unknown emoji asset: %s", asset_name.c_str());
78	            return;
79	        }
80	        const std::string& filename = filename_iter->second;
81	        if (!assets.GetAssetData(filename, src_data, src_len)) {
82	            ESP_LOGE(TAG, "Failed to get asset data for %s", asset_name.c_str());
83	            return;
84	        }
85	
86	        anim_player_set_src_data(player_handle_, src_data, src_len);
87	        anim_player_get_segment(player_handle_, &start, &end);
88	        if (asset_name == "wake") {
89	            start = 7;
90	        }
91	        anim_player_set_segment(player_handle_, start, end, fps, true);
92	        anim_player_update(player_handle_, PLAYER_ACTION_START);
93	    }
94	}
