254	int mqtt_connect(const char *broker, uint16_t port,
255	                const char *client_id, const char *username, const char *password)
256	{
257	    printf("MQTT connecting: %s:%d\n", broker, port);
258	
259	    /* 保存配置 */
260	    strncpy(mqtt_config.broker, broker, sizeof(mqtt_config.broker) - 1);
261	    mqtt_config.port = port;
262	    strncpy(mqtt_config.client_id, client_id, sizeof(mqtt_config.client_id) - 1);
263	    if (username) {
264	        strncpy(mqtt_config.username, username, sizeof(mqtt_config.username) - 1);
265	    }
266	    if (password) {
267	        strncpy(mqtt_config.password, password, sizeof(mqtt_config.password) - 1);
268	    }
269	
270	    /* 创建 TCP 连接 */
271	    mqtt_socket = create_tcp_socket(broker, port);
272	    if (mqtt_socket < 0) {
273	        printf("TCP connect failed\n");
274	        return -1;
275	    }
276	
277	    /* 发送 MQTT CONNECT 包 */
278	    if (mqtt_send_connect() < 0) {
279	        printf("MQTT CONNECT failed\n");
280	        close(mqtt_socket);
281	        mqtt_socket = -1;
282	        return -1;
283	    }
284	
285	    mqtt_config.connected = true;
286	    printf("MQTT connected\n");
287	
288	    /* 订阅命令主题 */
289	    char topic[128];
290	    snprintf(topic, sizeof(topic), "zhi_ai/%s/command", client_id);
291	    mqtt_subscribe(topic, 1);
292	
293	    return 0;
294	}
