503	/* 发送 HTTPS POST 请求（使用 vela_tls 客户端） */
504	static int https_post(const char *url, const char *body)
505	{
506	    char host[128] = {0};
507	    int port = 443;
508	    char path[256] = {0};
509	    char full_path[512] = {0};
510	
511	    /* 解析 URL: https://host[:port]/path */
512	    if (sscanf(url, "https://%127[^/]:%d/%255s", host, &port, path) < 2) {
513	        if (sscanf(url, "https://%127[^/]/%255s", host, path) != 2) {
514	            printf("https_post: invalid URL: %s\n", url);
515	            return -1;
516	        }
517	    }
518	
519	    snprintf(full_path, sizeof(full_path), "/%s", path);
520	
521	    char port_str[8];
522	    snprintf(port_str, sizeof(port_str), "%d", port);
523	
524	    printf("push: POST https://%s:%d%s\n", host, port, full_path);
525	
526	    /* 调用 vela_tls HTTPS 客户端 */
527	    int status = vela_https_post_json(host, port_str, full_path,
528	                                      body, NULL, 0, 10000);
529	    printf("https_post: status=%d\n", status);
530	    return status == 200 ? 0 : -1;
531	}
