893	/* 发送 MQTT CONNECT 包 */
894	static int mqtt_send_connect(void)
895	{
896	    uint8_t packet[512];
897	    int pos = 0;
898	
899	    /* 固定头: CONNECT = 0x10 */
900	    packet[pos++] = 0x10;
901	
902	    /* 可变头 */
903	    uint8_t variable_header[] = {
904	        0x00, 0x04, 'M', 'Q', 'T', 'T',  // 协议名
905	        0x04,  // 协议级别 (MQTT 3.1.1)
906	        0x06,  // 连接标志：下面按实际内容再补（见注释）
907	        0x00, 0x3C,  // 保持连接时间 60 秒
908	    };
909	
910	    /* 连接标志必须和 payload 里真实带了什么字段一致。
911	     *
912	     * 原来硬编码 0xC2（用户名+密码+遗嘱+清理会话），但下面只在 username /
913	     * password 非空时才往 payload 里追加对应字段 —— 两个都为空时，标志声称
914	     * "有用户名密码"、payload 里却没有，broker 判定报文非法，直接把连接关掉。
915	     * 表现就是「TCP 连得上，但永远收不到 CONNACK」。
916	     *
917	     * bit1=清理会话(0x02) bit2=遗嘱(0x04) bit7=用户名(0x80) bit6=密码(0x40)
918	     */
919	    if (mqtt_config.username[0]) {
920	        variable_header[7] |= 0x80;
921	    }
922	    if (mqtt_config.password[0]) {
923	        variable_header[7] |= 0x40;
924	    }
925	
926	    /* 构建载荷 */
927	    uint8_t payload[256];
928	    int payload_pos = 0;
929	
930	    /* 客户端 ID */
931	    int client_id_len = strlen(mqtt_config.client_id);
932	    payload[payload_pos++] = (client_id_len >> 8) & 0xFF;
933	    payload[payload_pos++] = client_id_len & 0xFF;
934	    memcpy(&payload[payload_pos], mqtt_config.client_id, client_id_len);
935	    payload_pos += client_id_len;
936	
937	    /* 遗嘱主题 */
938	    char will_topic[128];
939	    snprintf(will_topic, sizeof(will_topic), "zhi_ai/%s/status", mqtt_config.client_id);
940	    int will_topic_len = strlen(will_topic);
941	    payload[payload_pos++] = (will_topic_len >> 8) & 0xFF;
942	    payload[payload_pos++] = will_topic_len & 0xFF;
943	    memcpy(&payload[payload_pos], will_topic, will_topic_len);
944	    payload_pos += will_topic_len;
945	
946	    /* 遗嘱消息 */
947	    payload[payload_pos++] = 0x00;
948	    payload[payload_pos++] = 0x03;
949	    payload[payload_pos++] = 'O';
950	    payload[payload_pos++] = 'F';
951	    payload[payload_pos++] = 'F';
952	
953	    /* 用户名 */
954	    if (mqtt_config.username[0]) {
955	        int username_len = strlen(mqtt_config.username);
956	        payload[payload_pos++] = (username_len >> 8) & 0xFF;
957	        payload[payload_pos++] = username_len & 0xFF;
958	        memcpy(&payload[payload_pos], mqtt_config.username, username_len);
959	        payload_pos += username_len;
960	    }
961	
962	    /* 密码 */
963	    if (mqtt_config.password[0]) {
964	        int password_len = strlen(mqtt_config.password);
965	        payload[payload_pos++] = (password_len >> 8) & 0xFF;
966	        payload[payload_pos++] = password_len & 0xFF;
967	        memcpy(&payload[payload_pos], mqtt_config.password, password_len);
968	        payload_pos += password_len;
969	    }
970	
971	    /* 计算剩余长度并编码 */
972	    int remaining = sizeof(variable_header) + payload_pos;
973	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
974	
975	    /* 复制可变头和载荷 */
976	    memcpy(&packet[pos], variable_header, sizeof(variable_header));
977	    pos += sizeof(variable_header);
978	    memcpy(&packet[pos], payload, payload_pos);
979	    pos += payload_pos;
980	
981	    /* 发送 */
982	    return send(mqtt_socket, packet, pos, 0);
983	}
