1017	/* 发送 MQTT PUBLISH 包 */
1018	static int mqtt_send_publish(const char *topic, const char *payload, int qos, bool retain)
1019	{
1020	    uint8_t packet[1024];
1021	    int pos = 0;
1022	
1023	    /* 固定头 */
1024	    uint8_t type = 0x30;  // PUBLISH
1025	    if (qos == 1) type |= 0x02;
1026	    if (qos == 2) type |= 0x04;
1027	    if (retain) type |= 0x01;
1028	    packet[pos++] = type;
1029	
1030	    /* 剩余长度 = 2 + topic_len + payload_len [+ 2(包ID)] */
1031	    int topic_len = strlen(topic);
1032	    int payload_len = strlen(payload);
1033	    int remaining = 2 + topic_len + payload_len;
1034	    if (qos > 0) remaining += 2;
1035	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
1036	
1037	    /* 主题名 */
1038	    packet[pos++] = (topic_len >> 8) & 0xFF;
1039	    packet[pos++] = topic_len & 0xFF;
1040	    memcpy(&packet[pos], topic, topic_len);
1041	    pos += topic_len;
1042	
1043	    /* 包 ID（QoS 1 或 2 时） */
1044	    if (qos > 0) {
1045	        static uint16_t packet_id = 0;
1046	        packet_id++;
1047	        packet[pos++] = (packet_id >> 8) & 0xFF;
1048	        packet[pos++] = packet_id & 0xFF;
1049	    }
1050	
1051	    /* 载荷 */
1052	    memcpy(&packet[pos], payload, payload_len);
1053	    pos += payload_len;
1054	
1055	    return send(mqtt_socket, packet, pos, 0);
1056	}
