115	            robot_ui_set_face(ROBOT_FACE_HAPPY);
116	        } else if (strcmp(param, "thinking") == 0) {
117	            robot_ui_set_face(ROBOT_FACE_THINKING);
118	        } else if (strcmp(param, "sleepy") == 0) {
119	            robot_ui_set_face(ROBOT_FACE_SLEEPY);
