491	        if (++time_tick >= 200) {
492	            time_tick = 0;
493	            robot_ui_update_time();
494	        }
495	
496	        /* 运行 AI 模块 */
497	        if (g_ai_initialized) {
498	            sm_run(&g_sm_ctx);
499	
500	            /* 运行关怀确认状态机 */
501	            ai_checkin_tick(lv_tick_get());
502	
503	            /* 轮询 checkin 状态并更新 UI */
504	            checkin_snapshot_t snap = ai_checkin_snapshot();
505	            static checkin_state_t last_checkin_state = CHECKIN_IDLE;
506	            if (snap.state != last_checkin_state) {
507	                last_checkin_state = snap.state;
508	                switch (snap.state) {
509	                    case CHECKIN_SENDING:
510	                        touch_ui_update_checkin_state(TOUCH_CHECKIN_SENDING);
