175	/* ==================== 初始化触摸交互 UI ==================== */
176	void touch_ui_init(void)
177	{
178	    /* 初始化样式 */
179	    init_elder_styles();
180	
181	    /* 初始化提醒列表 */
182	    memset(reminders, 0, sizeof(reminders));
183	    reminder_count = 0;
184	
185	    /* 面板句柄复位: NuttX builtin 应用重新运行时 .bss 不清零,
186	     * 若残留上一次运行的面板指针, 之后 lv_obj_del() 会去删除已
187	     * 失效的 LVGL 对象而导致 hardfault */
188	    menu_panel = NULL;
189	    setting_panel = NULL;
190	    reminder_panel = NULL;
191	
192	    /* 获取当前活动屏幕 */
193	    current_screen = lv_scr_act();
194	    lv_obj_add_style(current_screen, &style_elder, 0);
195	
196	    /* 注册右滑手势：在主屏幕上任意位置向右滑动即可进入主菜单 */
197	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
198	                        LV_EVENT_PRESSED, NULL);
199	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
200	                        LV_EVENT_RELEASED, NULL);
201	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
202	                        LV_EVENT_CANCEL, NULL);
203	
204	    /* 加载持久化设置 */
205	    settings_load_from_file();
206	
207	    /* 开机时将保存的亮度下发到面板，避免显示亮度与设置不一致 */
208	    backlight_set(user_settings.brightness);
209	
210	    printf("touch_ui init done\n");
211	}
