213	/* ==================== 显示菜单 ==================== */
214	void touch_ui_show_menu(menu_type_t type)
215	{
216	    /* 记录当前菜单层级 */
217	    current_menu_type = type;
218	
219	    /* 清除所有旧面板. 注意 setting_panel 是活动屏的兄弟节点,
220	     * 不挂在 menu_panel 下, 只删 menu_panel 会遗留旧设置面板,
221	     * 导致新旧面板重叠且整棵对象树泄漏 */
222	    if (menu_panel) {
223	        lv_obj_del(menu_panel);
224	        menu_panel = NULL;
225	    }
226	    if (setting_panel) {
227	        lv_obj_del(setting_panel);
228	        setting_panel = NULL;
229	    }
230	    if (reminder_panel) {
231	        lv_obj_del(reminder_panel);
232	        reminder_panel = NULL;
233	    }
234	
235	    /* 创建菜单面板 */
236	    create_menu_panel(type);
237	}
