248	/* ==================== 返回上一级 ==================== */
249	void touch_ui_go_back(void)
250	{
251	    /* 隐藏所有面板 */
252	    touch_ui_hide_menu();
253	
254	    if (setting_panel) {
255	        lv_obj_del(setting_panel);
256	        setting_panel = NULL;
257	    }
258	
259	    if (reminder_panel) {
260	        lv_obj_del(reminder_panel);
261	        reminder_panel = NULL;
262	    }
263	
264	    /* 播放返回音效 */
265	    touch_ui_play_sound("back");
266	}
