268	/* ==================== 创建菜单面板 ==================== */
269	static void create_menu_panel(menu_type_t type)
270	{
271	    /* 菜单容器 */
272	    menu_panel = lv_obj_create(current_screen);
273	    lv_obj_set_size(menu_panel, LV_PCT(95), LV_PCT(85));
274	    lv_obj_align(menu_panel, LV_ALIGN_CENTER, 0, 0);
275	    lv_obj_add_style(menu_panel, &style_elder, 0);
276	    lv_obj_set_flex_flow(menu_panel, LV_FLEX_FLOW_COLUMN);
277	    lv_obj_set_flex_align(menu_panel, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
278	    lv_obj_set_style_pad_all(menu_panel, 20, 0);
279	    lv_obj_set_style_pad_row(menu_panel, 15, 0);
280	
281	    /* 标题 */
282	    lv_obj_t *title = lv_label_create(menu_panel);
283	    switch (type) {
284	        case MENU_TYPE_MAIN:
285	            lv_label_set_text(title, "[主] 主菜单");
286	            break;
287	        case MENU_TYPE_REMIND:
288	            lv_label_set_text(title, "[提] 提醒");
289	            break;
290	        case MENU_TYPE_SETTING:
291	            lv_label_set_text(title, "[设] 设置");
292	            break;
293	        case MENU_TYPE_ABOUT:
294	            lv_label_set_text(title, "[?] 关于");
295	            break;
296	        default:
297	            lv_label_set_text(title, "菜单");
298	            break;
299	    }
300	    lv_obj_set_style_text_font(title, &lv_font_ui_24, 0);
301	    lv_obj_set_style_text_color(title, lv_color_hex(0xFFEB3B), 0);
302	    lv_obj_set_style_pad_bottom(title, 20, 0);
303	
304	    /* 根据菜单类型创建内容 */
305	    switch (type) {
306	        case MENU_TYPE_MAIN:
307	            create_menu_item(menu_panel, "[语] 语音聊天", "与机器人对话", 0);
308	            create_menu_item(menu_panel, "[提] 查看提醒", "查看今日提醒", 1);
309	            create_menu_item(menu_panel, "[设] 设置", "音量、亮度等", 2);
310	            create_menu_item(menu_panel, "[急] 紧急呼叫", "联系家人", 3);
311	            create_menu_item(menu_panel, "[?] 关于", "版本信息", 4);
312	            break;
313	
314	        case MENU_TYPE_REMIND:
315	            create_reminder_list_items(menu_panel);
316	            break;
317	
318	        case MENU_TYPE_SETTING:
319	            create_setting_panel();
320	            break;
321	
322	        case MENU_TYPE_ABOUT:
323	            create_about_info(menu_panel);
324	            break;
325	
326	        default:
327	            break;
328	    }
329	
330	    /* 返回按钮 */
331	    create_back_button(menu_panel);
332	}
