366	static void create_reminder_list_items(lv_obj_t *parent)
367	{
368	    if (reminder_count == 0) {
369	        /* 空提醒 */
370	        lv_obj_t *empty = lv_label_create(parent);
371	        lv_label_set_text(empty, "暂无提醒\n\n点击 + 添加");
372	        lv_obj_set_style_text_color(empty, lv_color_hex(0x9E9E9E), 0);
