374	        lv_obj_set_style_text_align(empty, LV_TEXT_ALIGN_CENTER, 0);
375	        lv_obj_set_style_pad_top(empty, 50, 0);
376	    } else {
377	        /* 显示提醒列表 */
378	        for (int i = 0; i < reminder_count; i++) {
379	            if (reminders[i].active) {
380	                create_reminder_item(parent, reminders[i].title, reminders[i].time, i);
381	            }
382	        }
383	    }
384	}
