862	/* ==================== 右滑手势处理 ==================== */
863	
864	/* 在主屏幕上检测右滑手势，滑动超过 80px 显示主菜单 */
865	static void screen_gesture_event_handler(lv_event_t *e)
866	{
867	    lv_event_code_t code = lv_event_get_code(e);
868	
869	    if (code == LV_EVENT_PRESSED) {
870	        lv_indev_t *indev = lv_indev_get_act();
871	        if (indev) {
872	            lv_point_t p;
873	            lv_indev_get_point(indev, &p);
874	            swipe_start_x = p.x;
875	            swipe_tracking = true;
876	        }
877	    }
878	    else if (code == LV_EVENT_RELEASED || code == LV_EVENT_CANCEL) {
879	        if (!swipe_tracking) return;
880	        swipe_tracking = false;
881	
882	        lv_indev_t *indev = lv_indev_get_act();
883	        if (!indev) return;
884	
885	        lv_point_t p;
886	        lv_indev_get_point(indev, &p);
887	        int32_t dx = p.x - swipe_start_x;
888	
889	        /* 向右滑动超过 80px：子菜单回主菜单，主菜单关闭浮层 */
890	        if (dx > 80) {
891	            printf("[Gesture] Swipe right detected (dx=%d)\n", (int)dx);
892	            touch_ui_play_sound("click");
893	            menu_go_back_one_level();
894	        }
895	    }
896	}
