1010	/* ==================== 设置持久化 ==================== */
1011	
1012	static void settings_save_to_file(void)
1013	{
1014	    FILE *fp = fopen(SETTINGS_FILE_PATH, "wb");
1015	    if (!fp) {
1016	        printf("settings: save failed to open %s\n", SETTINGS_FILE_PATH);
1017	        return;
1018	    }
1019	
1020	    uint32_t header[2] = { SETTINGS_FILE_MAGIC, SETTINGS_FILE_VERSION };
1021	    fwrite(header, sizeof(uint32_t), 2, fp);
1022	    fwrite(&user_settings, sizeof(settings_t), 1, fp);
1023	    fclose(fp);
1024	    printf("settings: saved (vol=%d bright=%d auto=%d interval=%d)\n",
1025	           user_settings.volume, user_settings.brightness,
1026	           user_settings.auto_remind, user_settings.remind_interval);
1027	}
1028	
1029	static void settings_load_from_file(void)
1030	{
1031	    FILE *fp = fopen(SETTINGS_FILE_PATH, "rb");
1032	    if (!fp) {
1033	        printf("settings: no saved file, using defaults\n");
1034	        return;
1035	    }
1036	
1037	    uint32_t header[2];
1038	    if (fread(header, sizeof(uint32_t), 2, fp) != 2 ||
1039	        header[0] != SETTINGS_FILE_MAGIC ||
1040	        header[1] != SETTINGS_FILE_VERSION) {
1041	        printf("settings: invalid file header, using defaults\n");
1042	        fclose(fp);
1043	        return;
1044	    }
1045	
1046	    settings_t loaded;
1047	    if (fread(&loaded, sizeof(settings_t), 1, fp) != 1) {
1048	        printf("settings: read failed, using defaults\n");
1049	        fclose(fp);
1050	        return;
1051	    }
