/* 设置模式 */
void touch_ui_set_mode(robot_mode_t mode)
{
    current_mode = mode;

    /* 根据模式更新界面 */
    switch (mode) {
        case MODE_LISTENING:
            touch_ui_hide_menu();
            robot_ui_set_face(ROBOT_FACE_THINKING);
            robot_ui_set_status(ROBOT_STATUS_LISTENING);
            robot_ui_set_ai_reply("聆听中...\n请说话");
            break;
        case MODE_SLEEP:
            /* 降低亮度到 10%，显示休眠提示 */
            backlight_set(10);
            robot_ui_set_face(ROBOT_FACE_SLEEPY);
            robot_ui_set_status(ROBOT_STATUS_IDLE);
            robot_ui_set_ai_reply("休息中...\n触摸唤醒");
            break;
        case MODE_ALARM:
            /* 显示报警状态 */
            robot_ui_set_face(ROBOT_FACE_ALARM);
            robot_ui_set_status(ROBOT_STATUS_ALARM);
            robot_ui_set_ai_reply("紧急情况！\n请保持冷静");
            break;
        default:
            /* MODE_NORMAL: 恢复正常亮度 */
            backlight_set(user_settings.brightness);
            robot_ui_set_face(ROBOT_FACE_HAPPY);
            robot_ui_set_status(ROBOT_STATUS_IDLE);
            robot_ui_set_ai_reply("你好！我是智爱陪伴\n有什么可以帮你的吗？");
            break;
    }
}

