{
    (void)e;
    touch_ui_play_sound("click");

    /* 使用预设的提醒项（老人不需要手动输入） */
    const char *titles[] = {"吃药", "喝水", "散步", "测血压"};
    const char *times[] = {"08:00", "10:00", "16:00", "20:00"};

    static int next_reminder = 0;
    if (reminder_count < MAX_REMINDERS) {
        touch_ui_add_reminder(titles[next_reminder % 4], times[next_reminder % 4]);
        next_reminder++;

        /* 刷新提醒列表 */
        touch_ui_show_menu(MENU_TYPE_REMIND);
    }
}

