    msgs = daily[date]
    print(f"\n=== {date} ({len(msgs)} messages) ===")
    for m in msgs[:5]:
        print(f"  {m}")
    if len(msgs) > 5:
        print(f"  ... 还有 {len(msgs)-5} 条消息")
