# 提取每个日期的关键活动摘要
python3 << 'PYEOF'
import json
from collections import defaultdict
from datetime import datetime

sessions = [
    "/home/openvela/.claude/projects/-home-openvela-contest-work/0e3f0fa9-2ce4-496f-a9c9-f1d3f5c830e3.jsonl",
    "/home/openvela/.claude/projects/-home-openvela-my-claude-project/3e816775-8d52-4534-886b-b344cb84339d.jsonl"
]

daily = defaultdict(list)

for path in sessions:
    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
                ts = entry.get('timestamp', '')
                if not ts:
                    continue
                dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
                date = dt.strftime('%Y-%m-%d')
                role = entry.get('type', '')
                if role == 'human':
                    msg = entry.get('message', entry.get('content', ''))
                    if isinstance(msg, dict):
                        msg = str(msg.get('content', ''))[:300]
                    else:
                        msg = str(msg)[:300]
                    daily[date].append(f"[user] {msg[:250]}")
                elif role == 'assistant':
                    msg = entry.get('message', entry.get('content', ''))
                    if isinstance(msg, list):
                        # 提取 text 内容
                        for item in msg:
                            if isinstance(item, dict) and item.get('type') == 'text':
                                txt = item.get('text', '')[:250]
                                if txt and txt != 'No response requested.':
                                    daily[date].append(f"[assistant] {txt}")
                                break
                    elif isinstance(msg, dict):
                        txt = str(msg.get('content', ''))[:250]
                        if txt:
                            daily[date].append(f"[assistant] {txt}")
            except:
                pass

for date in sorted(daily.keys()):
    msgs = daily[date]
    print(f"\n{'='*60}")
    print(f"DATE: {date} ({len(msgs)} msgs)")
    print(f"{'='*60}")
    # 去重并显示前8条
    seen = set()
    count = 0
    for m in msgs:
        short = m[:80]
        if short not in seen:
            seen.add(short)
            print(f"  {m[:200]}")
            count += 1
            if count >= 8:
                break
    if len(msgs) > 8:
        print(f"  ... 还有 {len(msgs)-8} 条")
